/* 平成13年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h13.committeeSessions.push(...[{"id":"h13-20011126-5","meetingId":"h13-cm11","date":"2001年11月26日","dateIso":"2001-11-26","committee":"総務委員会","time":"午前１０時０６分～午前１１時２１分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を40件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"三上委員","kind":"質問","question":"その３の工事ということになってきましたので、今回のは、その１とその２という工事をやった業者とは同じですか。そこのところをちょっと。","respondent":"西島経理課長","answer":"その１、その２と、その３は別の工事ですけれども、発注業者は一緒になってあります。","voiceIndex":5,"id":"exchange-001"},{"speaker":"三上委員","kind":"質問","question":"結局、こういうように３回に分けて工事そのものというのを入札しなければならないもんなんでしょうか。","respondent":"西島経理課長","answer":"その３の工事というのは管の工事で道路を掘っていくということで、いろんな問題が出てまいりますので、その分大変という要素ではかなりあるということで、それでも、２ページに記載がありますように、７社の公募がございましたけれども。","voiceIndex":9,"id":"exchange-002"},{"speaker":"林（宏）委員","kind":"質問","question":"建設委員会と重なるのかどうかわかりませんけれども、ちょっと教えてください。ここら辺の工事が非常に集中していますよね。それと一緒の時間帯でやっていくという。説明会のときに出られましたか。だれも出ていない。そんないわゆる地元への配慮というか説明、その辺のことで特別なことがあったら教えてください。","respondent":"西島経理課長","answer":"委員ご指摘の交通の対処の問題については、１１月１９日の説明会でもかなり出たというふうに聞いてあります。それで、その３工事は三ツ木通りが大きな工事になってまいりますので、ここは昼間の住宅地域ということで、昼間の作業でやるというふうに聞いてあります。","voiceIndex":11,"id":"exchange-003"},{"speaker":"林（宏）委員","kind":"質問","question":"昼間やると、また相当、これは銀六のほうに抜けて、第二京浜に抜けていく道路ですよね。夜は通れない。できるだけ交通渋滞とか、そういうことがないように。もう１点、この工事の後に公園の復旧工事というのが入ってくるんだけれども、その３工事が終わると、例えばその後は雨が降れば、公園の工事とは関係なく、もう使えるようになるということですか。","respondent":"西島経理課長","answer":"１点目の交通の件につきましては、所管のほうと話をしまして、要望を伝えさせて、混乱のないようにやってまいりたいと思います。","voiceIndex":13,"id":"exchange-004"},{"speaker":"林（宏）委員","kind":"質問","question":"そういうところを連携して、上の公園までも想定した埋戻しの作業というのを、この佐藤工業にやっておいてもらえば、その分が僕は公園のときに経費節減とかなってくるんじゃないのかなという気がするんだけれども、そのことについては全く切り離して、埋めるのは一たん埋める、また公園をつくるときには掘るよと、そういうことになっていかざるを得ないんですか。","respondent":"西島経理課長","answer":"私どもも専門ということではございませんし、その公園復旧工事がどんな形なのかというのは、まだ図面も見ておりませんので、細かいところまではちょっとご説明できないんですけれども、ロスのないような形で、所管と公園の先の形を見ながら。","voiceIndex":15,"id":"exchange-005"},{"speaker":"林（宏）委員","kind":"意見","question":"そうすると、これは埋めるときにそういうのを一緒に埋め込んでもらっておけば、トイレの一番お金のかかる部分の管を埋めるというか、水回りというの、その辺のこともあるから、よく担当の所管のところと協議をして、むだのないような工事のシステムにしていくようにお願いしておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":17,"id":"exchange-006"},{"speaker":"宮崎委員","kind":"質問","question":"１点ちょっと伺いたいんですけれども、ここはいつも雨が降ると水がたまってくるということなんですけれども、地盤がどんな感じだったのかよくわからないんですけれども、その辺の調査はどういうふうになっているのかというのと、あと、ちょっとよくマンション建設なんかやると、振動で家屋の影響がどういうふうになるかというような調査をやりますね。そこら辺のことはどうなんでしょう。","respondent":"西島経理課長","answer":"２点目の家屋被害の話だろうと思うんですけれども、これはやはり１１月１９日の地元説明会でその件について質問が出まして、家屋被害の調査をこれからして、それから工事に入るというふうに、家屋被害といいますか、家屋の状況を確認をして。","voiceIndex":18,"id":"exchange-007"},{"speaker":"宮崎委員","kind":"質問","question":"そこら辺の考え方はどういうふうに今考えておられるのか、お伺いしたいと思います。","respondent":"西島経理課長","answer":"当日の説明では、おおむね道路に面した５４件について調査をするということで納得をされたというふうに私どもは聞いてあります。","voiceIndex":20,"id":"exchange-008"},{"speaker":"宮崎委員","kind":"質問・要望","question":"もうちょっとまだ、私のところがいろいろ意見もあったものですから、実際上の話し合いの説明会のときにはもしかして出なかったのかもしれないんですけれども、ちょっとそういう意見もあったものですから、検討をいただければ、今後のトラブルを未然に防ぐというふうになりますので、ぜひ点検いただければなというふうに思います。要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":22,"id":"exchange-009"},{"speaker":"土井副委員長","kind":"質問","question":"建設委員会とのかかわりがちょっと難しい兼ね合いですけれども、経理的な意味を含めてありますので、お伺いします。ありましたでしょうか、どうでしょうかということなんです。わかりませんでしょうか。","respondent":"市岡企画財政課長","answer":"ちょっと記憶だけですので、もしあれなら後で調べますが、最近確かに防水板の設置工事の助成申請がふえておりますが、それは主に五反田地区でございまして、この計画そのものがいわゆる東京都のクイックプランで。","voiceIndex":23,"id":"exchange-010"},{"speaker":"林（宏）委員","kind":"質問","question":"ちょっともう１点だけいいですか。この４ページの絵だけだと、道路のところの1)、2)、3)の実線が書かれているところだけ下水道があるように見えるんだけれども、実際は違いますよね。この3)のところの、いわゆる役所からずっと大崎にほうに延びていくＪＲに沿った道に下水道が整備されて、電車の下を百反の下から山手通りのほうにくぐるという、その工事はこれと何か関係してくる部分はあるんですか。","respondent":"西島経理課長","answer":"申しわけないですけれども、ちょっとそれは。","voiceIndex":25,"id":"exchange-011"},{"speaker":"林（宏）委員","kind":"質問","question":"次の、あしたじゃなくて、その先でいいですから、その工事との関連だけ聞いて、報告だけで結構ですから。それもむだな工事を、ここでちょん切らないで先っぽまでやればいいんだからというような気もしたんで、あした無理だったらその次で結構ですから、それだけ聞かせてください。お願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-012"},{"speaker":"林（宏）委員","kind":"確認","question":"そうすると、今度のこの茶色のところをやるという、紛らわしいんだけれども、この図でちょっと教えてください。全部陸地なんですよね。それをちょっと確認。これは陸地ですね。この桟橋というのは、以前何かここをつくるのに地権者というのが利用者というか、その方たちといろいろ話し合いをされて、納得をしてもらって、いよいよ工事に入るというふうな理解を僕らは持っていればいいんでしょうか。","respondent":"西島経理課長","answer":"そのとおりです。地権者というんでしょうか、権利者というんですか、その方とお話をして、工事をやっている間は仮設桟橋をつくって使っていただく。できましたら元のところ。若干位置が変わりますけれども、ずれて、そちらに戻る、そういうふうになります。","voiceIndex":34,"id":"exchange-013"},{"speaker":"林（宏）委員","kind":"質問","question":"何らかの金銭的なそういう妥協の方法があって、工事が始められるというふうにしたのかどうかということと、こんなにたくさん桟橋があって、こんなにたくさん船が着くんですか。この桟橋の設計というのは、なぜ２本、４本、６本、７本、８本あるようですが、その権利者との話し合いの過程をちょっと教えてくれますか。","respondent":"市岡企画財政課長","answer":"桟橋については、それぞれ既存の営業者、それから、ここに海上保安庁も施設がありますが、水域管理者が使うもので、余分な数は設置をしていないです。","voiceIndex":36,"id":"exchange-014"},{"speaker":"林（宏）委員","kind":"意見","question":"どうせこういうマリーナみたいな形で整備をしていくならば、いわゆるマリーナ的というか、マリーナという位置づけで水辺開発と絡んでいけば、いわゆる既存の権利者のためにここを整備するということから一歩進んで、区民の人たちも利用できる、あるいは水辺を生かした品川区の施策というのにつながるような気もするんですが、その辺については検討されたことがありますか。","respondent":"西島経理課長","answer":"それで、そのことについては、旧来あった権利者の分だけを設置をするというふうに聞いてあります。","voiceIndex":38,"id":"exchange-015"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"そうすると、じゃあ、この一帯をこういう桟橋がこういうように並んでくるならば、そういうベイエリアをつくり出してということを僕は考えていくのも品川区としての新しい土地利用というか、場所を利用していくということは大事なことだと思うので、これはもう設計、入札が済んでということですから、水辺についても一緒に考えていっていただきたいなというふうに思います。お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-016"},{"speaker":"三上委員","kind":"質問","question":"今、使用権か、漁業権というか、権利で営業の補償したという形で伺ったんですけれども、そうすると、これが完成した段階では、ここの事業指定船主というのか営業者、その人たちはきちんとした契約に基づいて、この設備を利用するという形で利用していくということで理解していいんですか。何件ぐらいそういうような形で民間業者というのはいらっしゃるのでしょうか。わかりませんか。","respondent":"西島経理課長、市岡企画財政課長","answer":"ですから、桟橋ができた後も、引き続き水面使用料についてはお支払いいただくという形になっているんだろうというふうに思います。今回排水工事を行っている施工業者がおりますので、計８名がそういう意味では水域権利者で、いわゆる釣り船等の営業的な権利者は、先ほど申し上げた５名です。","voiceIndex":41,"id":"exchange-017"},{"speaker":"三上委員","kind":"意見","question":"そうすると、その水面使用料というのは、金額がどうなっているかわからないけれども、そういうのは通常こういう施設利用をする場合の妥当な金額というのになってくるのか、それともこういう立派な施設をつくらなくても、同じ金額で別なところでやれば同じような金額を払っているというところもあるんだろうし、そこらあたりの、そうであれば、それなりに協力をしたということはあるのかわからないけれども。","respondent":"市岡企画財政課長","answer":"正直言って、詳細は私も理解が行き届かないところなんですが、これはいわゆる港湾法に基づく水域占用料というものを港湾管理者である東京都が取っているものなんですが、その占用料の規定に、恐らくそういう適正な占用料を定めたルールがあるのではないかというふうに。","voiceIndex":44,"id":"exchange-018"},{"speaker":"土井副委員長","kind":"質問","question":"それが今度桟橋という、そういうものができるわけですね。さあ、これをだれが管理して、責任をあととるのというところがどうなるのかなというのが気になって、当然やるとすれば都で、品川区にやれとは言わないだろうとは思うけれども、しかし聞きたいなというところなんですよね。わかりますか。桟橋はこれからメンテしていくのは事業者なんですか、東京都なんですか。","respondent":"西島経理課長","answer":"特に公有水面を埋め立てた後の所属の問題とかというのは、これからまた決まってくる問題で、桟橋もこれも受託工事ですので、持ち主は東京都ということになりますので、当然メンテナンスは東京都ということになろうと思います。","voiceIndex":47,"id":"exchange-019"},{"speaker":"北野委員","kind":"質問","question":"この工事は、あと何年ぐらい、この工事というか、桟橋を動かすというのは、あと何年ぐらい続くんですか。埋め立てのほうは期限が来年初めということで、急遽そのようにしたということなんですけれども、あと完成するのには、大体何回ぐらいの工事を。部分部分工事していきますよね。だから長いのかなと。完成はどのくらいを目指しているのですか。","respondent":"西島経理課長","answer":"これができるのが、私どもが聞いてありますのが平成１０年代の後半というふうに聞いてあります。","voiceIndex":49,"id":"exchange-020"},{"speaker":"北野委員","kind":"質問・要望","question":"その経緯で、この上を今度何にするかというのが決まるということで、公園が希望という声が出ているところかと思うんですけれども、じゃあ、完成して１８年以降、大体１８年以降にその上の部分は検討していくのか、その前から検討を始めるのかというところをちょっとお伺いしたいのと、所有権が決まらないと、その上に公園ができるということに対して、区のほうからは何も発言していけないのか。","respondent":"市岡企画財政課長","answer":"先ほどちょっとご説明したとおり、埋立免許の切れる来年６月までに埋立の工事は終わって、その後、経理課長がご説明したとおり、雨水貯留池の工事を平成１０年代の後半というふうに今申し上げたんですが、この貯留池の工事をしていく過程とすり合うような形で。","voiceIndex":51,"id":"exchange-021"},{"speaker":"北野委員","kind":"質問・要望","question":"わかりました。では、ぜひ住民の近隣の方の希望を聞いて、よりよいものをつくっていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":53,"id":"exchange-022"},{"speaker":"林（宏）委員","kind":"質問","question":"ちょっともう１回、この絵のグリーンにいくところが工事のところなのか、大きいと屋根がついているようなところを工事するのですか。ちょっともう１回、どんな形なのか場所の説明してもらえたら。","respondent":"西島経理課長","answer":"ここの部分です。それで、１４ページの図面は、図面の関係で左右がちょっと反対になってきますけれども、右側が大崎駅のほうからきたところで、そこが左側が今言いました６枚の屋根の部分、左右１２枚、下側に階段ができまして、その横にエレベーターが設置をされるです。","voiceIndex":58,"id":"exchange-023"},{"speaker":"林（宏）委員","kind":"確認","question":"もう１回確認します。１４ページでいくと、一番上の絵は線路側から山手通り側を見た絵ですよと。それから、真ん中というか、中段の絵は、ヘリコプターから見た絵ですよと。それから、１３ページのは、大崎駅の大きい四角の下の真四角に近い部分から６枚ですよということですか。この真四角の白い部分も入るんですか。","respondent":"西島経理課長","answer":"そこの部分から６枚です。それと、ちょっとあれですが、階段の部分がこのへりにちょっと見える、この６枚の上にちょっと出ている２枚がありますけれども、それは階段の部分で、右側がエレベーターというふうにご理解いただけるかと思います。","voiceIndex":60,"id":"exchange-024"},{"speaker":"林（宏）委員","kind":"質問","question":"何かそっちで意見が違っているようですね。理事者のほうでいろいろ意見が飛び交っていますけれども、統一した意見で教えてください。","respondent":"南雲都市開発課長","answer":"〔「そこを説明してくれないと」と呼ぶ者あり〕はい。歩道上にありますちょうどこの白い正方形が出っ張っているようなところがありますが、ちょうどこの部分から歩道上におりるような階段がついてあります。","voiceIndex":62,"id":"exchange-025"},{"speaker":"林（宏）委員","kind":"質問","question":"違うんじゃないですか。１４ページの絵から言うと、１４ページの絵の中段の緑で囲んであるところの右側に出っ張っているところが１３ページの白い部分に当たるんじゃないですか。","respondent":"南雲都市開発課長","answer":"ということで、出っ張っているところは全く新しくつくるわけではありませんが、高さの調整などで一部手直しをするということでございまして、それから、全く新しくつくるのは、この１４ページの図面で言いますところの、この緑の部分です。","voiceIndex":64,"id":"exchange-026"},{"speaker":"林（宏）委員","kind":"質問","question":"下の部分ね。わかりました。一応、絵の感覚がわかりましたので、ちょっと検討してもう１回質問をします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":66,"id":"exchange-027"},{"speaker":"三上委員","kind":"質問","question":"わざわざこれをつけかえなきゃならないという理由はないんじゃないですか。ちょっともう１回きちんと言っていただけると。今でもこの階段があるということで、それは利用されているわけですから、人の流れ的には問題ないわけですよね。","respondent":"南雲都市開発課長","answer":"将来、東五反田地区ではほかにも再開発が進められるということで、今回の１期工事の先のほうですね、１３ページの図面でいきますと右側に延びている部分ですが、これにつきましては、将来再開発が進んだ段階で、さらに延長していくという予定になっております。","voiceIndex":67,"id":"exchange-028"},{"speaker":"宮崎委員","kind":"質問","question":"実は２点ほどお聞きしたいんですけれども、今、財源が出たということで、半々で地元と国庫という説明があったんですけれども、国庫のほうはどういう内容で出てくるのか、改めて聞いておきたいんですけれども。今回は半々なんですけれども、これは何で半分ずつになっているのか。一体としてやらないのかという、そこら辺のところの意味というのはわからないので。","respondent":"市岡企画財政課長、南雲都市開発課長","answer":"この補助制度は、前に予算のときにご説明しました都市再生総合整備事業という、品川区の大崎駅周辺地区や、荏原市場跡地の整備、全体を通じて公共施設整備に充てるという新しい国の補助金でございまして、これの補助率が２分の１で。どうして今回この半分だけといいますか、左側の部分だけかですが、この今回つくりますところの階段、エレベーターについては、二丁目第１地区へのアクセスの改善ということで、二丁目第１地区が半分負担するですが。","voiceIndex":71,"id":"exchange-029"},{"speaker":"宮崎委員","kind":"質問","question":"そうすると、まず今の１期のほうは二丁目第１地区の範囲だということ。それで、２期のほうは第３地区のということなんですか。例えばエスカレーターとか、そういう義務というか、バリアフリーでの取り組みというのは余り、二丁目第３地区のほうは、そういう義務というか、バリアフリーとの関係では、余り責任を持たなくていいということなんでしょうか。","respondent":"南雲都市開発課長","answer":"ということで、全体としては、大崎駅東口をおりまして、東五反田のほうに行く車いすの方の通路を確保するということで、それをこれは厳密にどこまでがどの地区ということは分けられませんで、開発の中で段階的に整備する上で区切りがいい場所で役割の分担。","voiceIndex":74,"id":"exchange-030"},{"speaker":"宮崎委員","kind":"質問","question":"ちょっと聞き方が悪かったのかもしれないのですけれども、この図面を見ますと、例えば第３地区のほうに向かうのは、エスカレーターとかもないんだけれども、こっちに行くというのは、さっきのお話だと、一応費用分担とか、役割分担ですね、第１地区と第２地区とどっちがどういうふうに持つかということなんですけれども、第２期になると。","respondent":"南雲都市開発課長","answer":"このエレベーターについては、東口全体の方を対象にしたエレベーターということで、二丁目第１地区も東口第３地区も、今回つくりますエレベーターで身障者、高齢者の方に対応するですが、施工の費用分担ですとか、時期を区切る上で。","voiceIndex":76,"id":"exchange-031"},{"speaker":"林（宏）委員","kind":"質問","question":"利用する方も、駐輪場がよく利用されるという意味からも、その再開発にらみだけではなくて、利用する方の立場になれば、これは一遍につくっちゃう、工事そのものはそんなに難しい工事じゃないわけでしょう。それで、なぜつくらないのか、わかったら教えてほしいけれども、これは別々につくったほうが何割増しかになると思うのね。それが一つと、なぜこんなに長くつくらなきゃいけないの。","respondent":"南雲都市開発課長","answer":"それは、この今回の工事の先の延ばしている部分については、東口第３地区で開発が行われますと、住宅ですとかオフィスが相当できまして、そこに勤める方、住んでいる方が利用されるということで、この延長部分については東口第３地区が負担をするという予定になっておりますが。","voiceIndex":78,"id":"exchange-032"},{"speaker":"林（宏）委員","kind":"質問","question":"再開発絡みだというのはわかってますよ。だけれども、税金をつぎ込んでつくっていくのに一番むだのないつくり方をするには、この１４ページの上の図の左側をちょん切っちゃうところから、階段をおろしちゃえば、第３地区の負担もかからないじゃない。と、僕はむだのない税金の使い方は、そういうやり方じゃないのかなという気がするんだけれども、何か理由があるんですかと聞いている。蛇腹を延ばす理由が。","respondent":"南雲都市開発課長","answer":"これについては、さらに環状６号線の陸橋下をくぐりまして、そこから先にもまだもう少し登っていくというものも将来つくる可能性もあるです。","voiceIndex":80,"id":"exchange-033"},{"speaker":"林（宏）委員","kind":"質問","question":"東五反田第３の再開発で、それほど人がここの歩道を利用するという計算が成り立つぐらい計画が進んでいるんですか。ここの階段をつくっておいて、それほど人がここに集中してくるとなったら蛇腹をつくればいいじゃないですか。ただ単に再開発の時期がこっちだから、ここに延ばしたというだけじゃないんですか。歩道にあふれるほど人が来ると、本気で考えていらっしゃいますか。想像だけだと思うな。","respondent":"南雲都市開発課長","answer":"ということで、将来東口第３地区ですとか東五反田地区の開発が完了しますと、今の地上部分の歩道だけでは十分の歩行者を処理できないということで、ここについては地上部と、それから２階部分のデッキと両方で歩行者をということで。","voiceIndex":82,"id":"exchange-034"},{"speaker":"林（宏）委員","kind":"質問","question":"その検討委員会でつくられた、ここをどのくらいの人が利用するかという数字が出ていたら、次でいいですから聞かせてください。それだけお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":84,"id":"exchange-035"},{"speaker":"土井副委員長","kind":"意見","question":"デッキのつくりの問題で今議論になっていますので、的確な説明をしていただかなきゃいけないのは、右側のヘアピンの絵がありましたよね。ここが大きな役割をしているということをお話しいただかないと、理解がしにくいんですよ。普通そちらから来た人は、もうずっと下まで行かないと、こちらに来れないわけですよ。言っている意味、わかるでしょう。だと私は思うんですけれども、間違っていますか。","respondent":"南雲都市開発課長","answer":"副委員長ご指摘のとおり、現在、陸橋にこのぐるぐる回っていますらせん状のスロープがあります。このスロープにも、今回このデッキは将来延長された場合には接続するようになっておりまして、今あるスロープとスムーズに接続するというような設計を考慮することになっております。","voiceIndex":85,"id":"exchange-036"},{"speaker":"三上委員","kind":"質問","question":"今、こちらの通路のほうはわかりましたけれども、ニューシティとその東五反田の再開発のビルのほうとのつながりというのは、今再開発をやろうとしているところと、地上部分に空間の通路をつくるわけでしょう。それがゲートシティとつながるかというと、ゲートシティ、それからニューシティ、それからその東五反田再開発で、同じ２階部分でずっとつながるという計画というのはないんですか。","respondent":"南雲都市開発課長","answer":"構想としては、ニューシティから北側の第３地区のほうまで、将来的には接続できるようには計画しておりますが、今回再開発を行う部分とニューシティの間に千代田グラビアの工場がありまして、これについては今回再開発を行いませんので。","voiceIndex":88,"id":"exchange-037"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"正午に帰ってきて、午後からまたわざわざやらなきゃいけないという。時間はあるわけですね。じゃあ、お願いします。それから、区が行うペイオフ対策というものの波及、区民あるいは区の中小企業の業者とかに与える影響とか、いろいろあると思うんですけれども、その辺についての区側の対策とか、見解とか、先々の対応策があったら聞かせていただきたいなというふうに思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":92,"id":"exchange-038"},{"speaker":"三上委員","kind":"意見","question":"要するに東京三菱と今言っているけれども、東京銀行と三菱銀行が一緒になったというのはわかるんですけれども、そういう、今まで都市銀行って十何行あったというのが、こう一緒になって、それがどういうグループに編成されたのかという部分については、何かそういうのが、資料的にあれば、ちょっと用意していただければ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":100,"id":"exchange-039"},{"speaker":"宮崎委員","kind":"確認","question":"今のきんだぁくらぶの件でちょっと確認しておきたいんですけれども、今、日本音楽学校のほうからそういう認可化したいという申し入れがあって、区のほうの対応について、ちょっともう１回確認したいんですけれども。","respondent":"太川総務課長","answer":"この認可に当たりまして、具体的には保育課の中身になってまいりますけれども、日音のほうといたしましては、計画的な保育等々を含めまして、ぜひ認可保育園という形でやっていきたいんだということでございまして。","voiceIndex":105,"id":"exchange-040"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1564#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":22023,"voices":107}},{"id":"h13-20011127-6","meetingId":"h13-cm11","date":"2001年11月27日","dateIso":"2001-11-27","committee":"区民委員会","time":"午前１０時０３分～午後３時２５分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を15件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"原委員","kind":"質問","question":"今ご説明いただきまして、これは東京都のガイドラインですよね。こういうような形は、例えば全国的にどこかほかで、要するに全国的規模で統一されたものを考えているとかという、そういう今後の話というのはないんでしょうか。","respondent":"宮地区民課長","answer":"これは、平成１３年４月から大もとの法律がかわったばかりで、今のところは、こうしたマークに取り組んでいるのは東京都だけです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"金高委員","kind":"質問","question":"実施時期が１２月１日なんですが、表示の仕方でもって、これはこのマークが大きなのが出ていますけれども、大体こういう遺伝子組み換えというのは、非常に皆さん関心を持っているわけなんですね。例えばこちらの左のほうの生産者というか、製造者というか、何かというのは裏に大体書いてありますけれども、この表示というのはやはり裏につくものなんですか。表につくものなんですか。説明してください。","respondent":"宮地区民課長","answer":"ちょっと開いたところの左側、第３、表示方法等と書いてあるところがあるんですけれども、一応、このマークを見やすい場所に見やすい大きさで表示するものとなっているということで、特に大きさなどについての指示はありませんので、なるべく目につきやすいところということです。","voiceIndex":8,"id":"exchange-002"},{"speaker":"石田副委員長","kind":"質問","question":"そこら辺は、だから推進してご協力いただけるところがどれぐらいあると見込んでいるのかなというのが、大手とかはある程度すぐ対応してくれるんでしょうけれども、現実問題として、どれぐらいこのマークがついたものが出回ると予想しているのかというところがわかれば教えてください。","respondent":"宮地区民課長","answer":"それから先にどの程度協力が得られるかというのは、もうちょっと１２月の実施の動向を見ませんとわかりませんが、東京都の話ですと、かなり前向きに取り組んでいっていただけるのではないかという感触だそうです。","voiceIndex":10,"id":"exchange-003"},{"speaker":"菊地委員","kind":"質問","question":"昨日、申し上げたとおりなんですけれども、課長のほうからちょっとその辺の説明を受けまして、その後で質問したいことがあれば。","respondent":"市川産業振興課長","answer":"ハローワークとの連携による就職相談実施に関するフォローということで、私のほうから説明をします。","voiceIndex":17,"id":"exchange-004"},{"speaker":"菊地委員","kind":"質問","question":"ただ、職を見つけてというんですけれども、もちろんそうなるとハローワークに行くわけですけれども、これが今の実情の中で、なかなかハローワークに行っても、５０歳代だと、この間伺ったときに、５５歳を過ぎますと、求人倍率が０.１５倍ぐらいですからね。例えば今の荒川区の話ですけれども、そういう体制というのはできないものなんですか。","respondent":"市川産業振興課長","answer":"ただ、私ども地域経済の産業振興ということを担当している立場から、この側面支援ということで、雇用に対する何らかの働きかけをしていくということではやぶさかでないということは、これまで申し上げてきておりますので、ハローワークとの連携ということは、そういう意味で。","voiceIndex":19,"id":"exchange-005"},{"speaker":"菊地委員","kind":"質問","question":"〔「雇用に関して」と呼ぶ者あり〕側面からの支援ということなんだけれども、今言った荒川区なんかでやった体制の、今課長の答弁はちょっと私がよくわからなかったんですけれども、荒川区やなんかでやったような体制というのは、地元の事情とはいえ、品川にも当然のことながら今の失業率から考えればあるわけですけれども、今のお答えというのは。","respondent":"市川産業振興課長","answer":"私どものほうも、先ほどハローワーク五反田とこれから意見交換をしていくということは、地元の品川区の雇用情勢というものを専門の立場から見てどのように分析をして、どのような対策が有効かということをハローワークがどういうふうに考えているか。","voiceIndex":21,"id":"exchange-006"},{"speaker":"菊地委員","kind":"質問・要望","question":"はい、わかりました。それと、もう１点だけ、桜井委員のした質問の中で、シルバー人材センター、これは区独自で平成１４年度から相談体制をするんだというお話がありましたけれども、ちょっとその辺で具体的なところを現時点でわかっているところをお教え願いたいんですけれども。","respondent":"市川産業振興課長","answer":"それで、そこを要するに地元の高齢者には地元企業の振興をということのマッチングから、このすき間を埋めることによって新たな雇用創出ができないかということで、来年度からの実施に向けて、実際にはシルバー人材センターを組織的に活用することによって。","voiceIndex":23,"id":"exchange-007"},{"speaker":"石田副委員長","kind":"質問・要望","question":"ちょっと話がずれるかもしれないんだけれども、今の雇用創出というお話で、よくご存じのように、６４歳までの方には、今補助金が出る、５０歳以上かな、ということで、企業も大分採用していて、変なことを言うと、１年間働いていただければ補助金がいただけるということだから、６３歳の人を雇おうという動きをかけている業者の人もいるやに伺うんだけれども、そうすれば、６０歳までで。","respondent":"市川産業振興課長","answer":"それで、私どものほうとしては、そこまでの受けとめ方しかできないのが現状でして、少なくとも経済対策というか、産業振興と雇用対策というのは表裏一体の関係であるということからすれば、国の助成金にしろ、地方自治体の助成金にしろ。","voiceIndex":26,"id":"exchange-008"},{"speaker":"原委員","kind":"質問・要望","question":"ちょっと先ほどの話で出てきたことなんですけれども、何と言ったらいいのかな、シルバーハローワークと言ったらいいのかな、要するに、シルバー人材センターの部分と、それからシルバーのそういうハローワーク的な捕え方の部分、これは出していくわけなんで、シルバー人材センターとの整合性はどういうふうに考えられていくんですか。","respondent":"市川産業振興課長","answer":"一番大きな点は、やはり職業につく、就労ということが今までのシルバー人材センターの中で、多少対応の甘さはありますけれども、あえてこれを一言であらわすと一時的な就労というようなイメージのものが今までのシルバー人材センターの中で行われてきた。","voiceIndex":28,"id":"exchange-009"},{"speaker":"原委員","kind":"質問","question":"そうすると、シルバーの一つの事業は、一応パート的な一時的な、その日の就労という形態をとっていく。しかし、ほかの形をそこで、就労という形をそこにまた一つつくり出すんだということでは、別な組織として、組織化がどういうふうにされるのかわからないけれども、それでいこうということなんですか。","respondent":"市川産業振興課長","answer":"基本的なイメージとしては、今おっしゃられたようなイメージであると思います。","voiceIndex":30,"id":"exchange-010"},{"speaker":"金高委員","kind":"質問","question":"それぞれ地域がありますけれども、これを見ると、荏原第２地区がちょっと抜けちゃっているというのは、何かやっぱり理由があったか、あるいは発表する方が出られる人がいなかった、その辺をちょっと含めて、せっかくですから、それぞれ競い合うというのも一つの方法かもしれないですけれども、その辺ちょっと２点ばかり。","respondent":"長田地域活動課長","answer":"ただ、そのエリアから、例えば一番多いのは平塚中学校ですけれども、平塚中学校あたりにもちろん行っているわけですけれども、そういったようなことと、それから全体の時間との関係で１２名に絞らせていただいた、こういうことです。","voiceIndex":38,"id":"exchange-011"},{"speaker":"本田委員","kind":"確認","question":"そのことをちょっともう１回確認をしておきたいと思うのと、この大きな世界規模での問題で、先進国が好きなだけ産業発展のために、この温暖化に、その原因をつくってきた。ですから、これから大綱の見直しとかいろいろ出てくるわけですが、区としては、その辺はどんなふうにとらえているのか。","respondent":"金井環境課長","answer":"この中で地球温暖化も含めたさまざまな取り組みを、具体的な区の環境の方針という形で決めさせていただきたいというふうに考えて検討しています。これは来年度決定ではございませんので、今予算要求の段階ですので、環境課としてはそういう方向で推進していきたい。","voiceIndex":46,"id":"exchange-012"},{"speaker":"本田委員","kind":"質問・要望","question":"ＣＯＰ７がこういう形でまとまってきたということをある面では歓迎をしながら、国民の世論をもっと強めていく必要が重要ではないかということを思っておりますので、請願との関係で言えば、もうあれでいいんだということではなくて、何らかのアクションを起こせるように、今後推移を見ながら当委員会ではさらに検討をするように要望したいというふうに思っております。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-013"},{"speaker":"原委員","kind":"質問","question":"今お話に出ていた問題についてですけれども、まず、林和也委員のほうで、うちのほうを代表して、中央公園の人工芝をということで区長のご意見を伺ったわけですけれども、これは、党内でかなり論議がありまして、最初に人工芝という話が出たときに、何であそこで人工芝にしなきゃいけないのかから始まって、いや、あそこは天然芝をやるべきだという結論が出た上で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":49,"id":"exchange-014"},{"speaker":"菊地委員","kind":"質問・要望","question":"１点だけお聞きしたいんですけれども、今、原委員の言われた国内制度の整備とかというところで、これはもちろんまだこれから整備していくんだということなんですけれども、実際に今ある程度のどういう面を整備してという考え方というのは、区のほうでとられていればその辺を教えていただきたいのと、区にかかわってくる部分というのはどういうところが出てくるのかなというのがちょっとわかりましたら。","respondent":"金井環境課長","answer":"それで、そういう方向性の行動計画とか、そういったものもあるようですので、そういったものも見直されるのではないかと思いますけれども、具体的にどれとどれとどういった内容というのは、ちょっと今のところ、すべてについてはつかんでいないということを。","voiceIndex":51,"id":"exchange-015"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2314#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":24305,"voices":57}},{"id":"h13-20011127-7","meetingId":"h13-cm11","date":"2001年11月27日","dateIso":"2001-11-27","committee":"厚生委員会","time":"午前１０時０６分～午後２時４６分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を27件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"船波委員","kind":"質問","question":"通所授産施設のほうに関しては、既存のかもめ工房共同作業所を移転するということになっていますけれども、その現在のかもめ工房の運営主体と、この新しくできるほうの授産施設は、新しい社会福祉法人が運営するということですけれども、その関係はどうなるんでしょうか。","respondent":"田中健康課長","answer":"私どもとしましては、このかもめ工房の共同作業所の運営をされていますかもめ工房等運営委員会、こちらの皆さんにこの社会福祉法人の中で活躍していただくといいますか、お入りいただくように進めていきたいと考えております。","voiceIndex":5,"id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"新しくこの授産施設ができるということで、これはほんとうに家族会の方々の長年の要望でありましたので、支援センターともども、こういう運びになってほんとうによかったなというふうに思います。そしてまた、共同作業所についても、精神障害者の方が品川区内に３,２００名というふうに言われていますけれども、その中でそういう方々がどの程度いらっしゃるのかについて、お聞かせください。","respondent":"田中健康課長","answer":"この地域で生活されていらっしゃる精神障害の方ということで、今回、この社会復帰を目指すための私どもの想定をしておりますのは、生活支援センターのほうで登録制をしこうと考えていますので、隣の大田区の例を参考にしますと、登録総数が大田区は現在のところ。","voiceIndex":7,"id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この既存のかもめ工房共同作業所を移転するということなんですが、これは具体的にはどこの作業所を移転するのか、決まっているのであればそのことも教えてください。","respondent":"田中健康課長","answer":"第一、第二、第三とございまして、これは一応かもめの運営委員会のほうにもご相談申し上げてということになるかと思いますけれども、私どもとしましては、現在、荏原地区に２カ所ありまして、非常に不安定なロケーションということがありますので。","voiceIndex":9,"id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今でも共同作業所は、この後で審査される請願の中で、共同作業所をふやしてくださいという、そういう要望が家族会の中から出されていると思うんですが、これを一つなくして移転というふうな、新たに授産施設をつくるということじゃなくて、共同作業所を移転するというふうになった、そういうふうにした考えというのはどういうところから、家族会としては多分、授産施設もつくっていただきたい、そしてまた。","respondent":"田中健康課長","answer":"共同作業所四つというのは、あくまで今必要と思われる方の数をカバーするためといいますか、この一、二、三をある程度ベースに置いての考え方だというふうに理解しておりまして、例えば今回の場合も、定数上も５名ふやせるとか、いろいろ今後のロケーションを動かすに当たって。","voiceIndex":11,"id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"障害者の方の数からしても、３,２００名いらっしゃるというところから、そのうちのほんとうにわずか１００名ということですから、精神障害の方々にかかわっている、例えば保健婦さんですとか、こういう作業所の方々ですとか、そういうふうにかかわっている方々からすれば、もっともっとそういう共同作業所につなげたいという方は、たくさんいらっしゃるんじゃないかと思うんですけれども。","respondent":"小林品川区保健所保健サービス課長","answer":"あるいは、保健所のデイケア、作業所に通えるというのはある程度のレベルに達した方ですので、現在作業所の数はどの程度が品川区においてベストかというのは、なかなか申し上げられないとは思いますけれども、保健所で作業所に通所したくても空きがなくて。","voiceIndex":13,"id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"もう一つお聞きしたいんですが、支援センターとか授産施設に関しては、こういう中身にしていただきたい。例えば、訪問活動もしていただきたいとか、さまざまな内容の要望が家族会の方からの要望書の中で出されていますけれども、そういう検討というのはこれからされるということでよろしいんでしょうか。","respondent":"田中健康課長","answer":"ですから、支援センターのほうの訪問等も視野に入れた、それからホームヘルプ事業も来年度から開始しますし、その辺も含めた総合的な生活支援をできるようなという考え方で、これから検討を具体的にしていくという内容です。","voiceIndex":15,"id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひ家族会の方々の要望に沿えるような中身としても、より充実したものにしていただきたいというふうに思います。この職員の体制とか、そういうのももしも今の段階で、専門職がどういうふうに入るのかというのは書かれていますけれども、人数とか体制というのがわかったら、教えていただきたいと思います。","respondent":"田中健康課長","answer":"ただ、きょう、そこまでといいますか、実は併設をしますので、例えば整備基準のほうでも兼用可というふうになっておりますが、職員のほうにつきましても、そういう形で兼務が可ですとか、いろんな形がございまして、ちょっと複雑になるものですから。","voiceIndex":17,"id":"exchange-007"},{"speaker":"嶋委員","kind":"質問・要望","question":"３点ばかりお聞きをしたいと思います。一人で自分で行くのか、そこら辺がよくわからないので、もし一人で行くならば、ある程度バスの乗り継ぎが二つぐらいなら行けるかなという部分もあるかと思いますので、どのぐらいの地域から行かれるのか、教えていただきたいと思います。登録制のことと、どの時期にということと、それから、地域ということで、よろしくお願いします。","respondent":"田中健康課長","answer":"この辺は、もう少し先にいきまして、具体的な詰めかというふうに考えておりますが、一応開設をする３カ月から６カ月ぐらい前にはそういうことをお知らせして、準備を進められるようにできればなというふうには考えてあります。","voiceIndex":20,"id":"exchange-008"},{"speaker":"伊藤委員","kind":"質問","question":"二つお伺いいたします。一つは、授産施設のほうですけれども、新設の社会福祉法人を設立されるということですけれども、たしか前の請願の内容の中に法人をつくってほしいようなことがあったと記憶しているんですが、そういうふうなものが具体化してきたのかなという思いでいたんですけれども、それがそうなのかということが一つです。お願いいたします。","respondent":"田中健康課長","answer":"社会福祉法人の関係ですが、これは以前から安定的な運営主体といいますか、そういう形で検討してまいりましたが、基本的には授産施設等、法内施設を運用するのは、こういうきちっとした法人じゃなきゃいけないということで、私ども考えてまいりました。","voiceIndex":24,"id":"exchange-009"},{"speaker":"伊藤委員","kind":"質問・要望","question":"社会福祉法人ですけれども、安定運営ということで、これは前々から請願とかいろんな形で、私ども聞いていた内容がああいう形になってきてうれしいなとは思っているんです。だから、もしあれば、そういうようなものを十分に聞いてあげて、ただ返すのではなくて、また別な施設に転用していくというお考えはないでしょうかということ、二つをお聞かせください。お願いいたします。","respondent":"田中健康課長","answer":"ただ、できること、できないことは当然これからも出てくるわけですので、ご承知おきいただければと思います。","voiceIndex":26,"id":"exchange-010"},{"speaker":"伊藤委員","kind":"質問・要望","question":"何回か私たちもかもめ会の皆さんと懇談したり、いろいろお話を聞いております。ですから、お願いしたいのは、今の財政とか仕組みを十二分に考えながらでも、実は請願でできない、それから、言葉では出てきていない、いわゆる大変な現状を十分に区のほうは理解してあげて、さまざまな対応をとっていただきますように、改めて要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-011"},{"speaker":"鶴副委員長","kind":"意見","question":"社会福祉法人を設立して運営するということは、大変喜ばしいことで、かもめ会の願いでもありましたし、私も言及をしてまいりましたので、関心を持っているところですが、設立までのプロセス、これはどういうふうになるのかということです。どういう段取りで設立をされていくのかという点です。そのあたりのことをお知らせいただけませんか。","respondent":"田中健康課長","answer":"それで、私どもとしましては、１４年度に設立準備のための会合等を持つようにさせていただきまして、１５年には設立準備会という形で運用していって、１６年に認可を受ける段取りをつくっていきたいというふうに考えておるところです。","voiceIndex":29,"id":"exchange-012"},{"speaker":"鶴副委員長","kind":"意見","question":"そうしますと、この社会福祉法人が立ち上がった後は、この施設を含めて、既存の今までかもめ会が運営なさっていた第一、第二それぞれのところについては、その傘下におさまって、より安定的な運営ができると、こういうことになるわけですね。","respondent":"田中健康課長","answer":"委員ご指摘のとおりでございまして、トータルにその社会福祉法人でもって全体をカバーしていきたいというふうに考えてあります。","voiceIndex":33,"id":"exchange-013"},{"speaker":"鶴副委員長","kind":"質問","question":"そういうふうな点から見ると、余り単純な数で批判してほしくない。共同作業所の性格、あるいはこういう法内施設との違いというものをしっかり踏まえた上で論評してほしいと、こういうふうに私は思う。この社会福祉法人の名称というのは、準備会が立ち上がって、その中で決まっていくんですかね。やっぱり愛称型になるんでしょうか。ちょっとそこのところを、基本的な考え方をお伺いしておきたいと思います。","respondent":"田中健康課長","answer":"ネーミングまでは実はまだ具体的な検討に入っておりませんが、委員おっしゃるように、皆さんに親しんでいただける名称になっていっていただければというふうには考えております。","voiceIndex":35,"id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この施設を改修する費用についてお聞きしたいんですけれども、これは国からどれくらい補助金がどういうふうな形で出てくるのか。そして、運営についての補助とか、そういうものはどういうふうになっているのかについて教えてください。","respondent":"田中健康課長","answer":"生活支援センターのほうは、実は整備補助はないんですが、ただ運営につきましては両方とも、現在のところは国と都を合わせまして、区の負担が実質上ない程度に補助をいただけるというふうな見込みです。","voiceIndex":38,"id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"先ほどの続きで申しわけないんですが、共同作業所が今３カ所ありますけれども、そこのところで待機者という方はどれくらいいらっしゃるのか、教えていただけないでしょうか。","respondent":"田中健康課長","answer":"毎月私もこの運営委員会に参加させていただいておりまして、そこで毎月の待機者という形をご報告いただいております。先日のところで、第一が５名、第二が５名、第三が４名という形になっております。","voiceIndex":40,"id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"だから、そういうところではぜひ、もう一回要望ですけれども、共同作業所は存続という形でご検討いただいて、またこの希望の方が入れて、潜在の方も掘り起こしていけるようなことで、これは要望とさせていただきたいと思います。","respondent":"新美保健高齢事業部長","answer":"そういうことを含めて、我々はこれまでの共同作業所の整備から、この後グループホーム等もありますけれども、本格的に保健福祉施策をきちんと区としてどうやっていこうかと、この間、ご案内のとおり検討を重ねてまいりまして、今回第三次長期基本計画にきちんと計画を立てる形で。","voiceIndex":42,"id":"exchange-017"},{"speaker":"須藤委員","kind":"質問・要望","question":"社会復帰指導員というのとその辺の違いがどうあるのかということ。前に旗の台で心身障害者福祉会館をつくったときもいろんなお話が出てきましたので、その辺のところで近隣の方々のいろんなご要望が入ってきた場合に、これだけのスペースでいいのかどうかということも考えておかないといけないんじゃないかなという気がするんですけれども、そのあたりのお考えはいかがでしょうか。","respondent":"田中健康課長","answer":"現在の大崎第１地域センターのほうですが、４階建てで６１２平米あります。いろいろ私ども検討しまして、例えば授産施設は定員によりまして平米の基準がありますので、それ等を調整いたしますと、このような構成になるかなというふうに考えてあります。","voiceIndex":45,"id":"exchange-018"}]},{"id":"topic-02","title":"平成１３年請願第１６号、精神障害者の社会復帰支援に関する請願","agenda":"平成１３年請願第１６号、精神障害者の社会復帰支援に関する請願","exchanges":[{"speaker":"鶴副委員長","kind":"質問","question":"ホームヘルパーは、これまでもたびたび請願で審査したことですけれども、それで聞かなかったことがあったんですが、なぜこの精神障害者の家庭へのホームヘルパーというのはなかったんでしょうかという点。例えば、精神障害者の家庭であっても、高齢になった場合、高齢者に対するホームヘルパーだとか、普通の障害児者のところのホームヘルパーとかあるじゃないですか。","respondent":"新美保健高齢事業部長","answer":"したがいまして、今回、私ども精神障害者の方のホームヘルプサービスを今具体的な準備で、それぞれご相談いただいたり、あるいは共同作業所などへ、いろいろ通っていただいたりしている方、あるいは保健所に相談に見えている方、そういうところからニーズをきちんと精査しまして。","voiceIndex":56,"id":"exchange-019"},{"speaker":"鶴副委員長","kind":"質問","question":"それで、課長の今のご説明によると、１４年度にこのホームヘルパーの派遣制度も採用される運びというふうに聞いて、うれしいんですけれども、そうすると、いろんな基準というのをつくっているんでしょうかね。あるいは、直営のヘルパーさんを派遣していくというふうになるのか、基本的な考え方はどうなんでしょうか。","respondent":"新美保健高齢事業部長","answer":"派遣の決定の基準ですけれども、基本的にはこれはもうご案内のとおり、どの福祉サービスも現在の基本的考え方は自立支援ということになりますので、やはり自立支援、あるいはよりよい生活のために必要性の判定というのは、これは公的なサービスですので、保健所、保健センター。","voiceIndex":58,"id":"exchange-020"},{"speaker":"鶴副委員長","kind":"質問","question":"もう１点だけお聞きしておきたいのですけれども、第４作業所を早急にということですが、これは１６年度末にできるこの授産施設によって、ある程度この希望はそこで実現できると、こういうふうな理解でよろしいんでしょうか。私はそういうふうに思うんですが。","respondent":"田中健康課長","answer":"１６年に私どもとしましては、現在のニーズを含めた部分を一応受けとめられるんではないかなというふうに考えております。","voiceIndex":60,"id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"ホームヘルプサービスのところで、今ご説明いただいたんですけれども、このかもめ会の方々の意見というところを見すると、やはりホームヘルパーの研修や訓練をきちんと実施してほしいという中身が書かれているんですけれども、平成１４年度から始まるということで、間もなくもう数カ月で開始されるわけですけれども、ここら辺のところがどうなっているのかについてお聞かせください。","respondent":"田中健康課長","answer":"今回のホームヘルプを実施するに当たりまして、現在、東京都のほうのホームヘルパーの研修、あるいは区としてのそういう形の研修を実施するように準備をしておりまして、今、部長のほうから報告がありましたヘルプの主体の方々を中心に呼びかけをして、受けていただいて。","voiceIndex":63,"id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この精神障害者の援助ということなので、やはりこの病気のことについてもきちんと理解した方でないとなかなか難しいということがあると思いますので、ぜひそこのところは充実した中身でやっていただきたいと思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":65,"id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"きのうの審査の請願の継続ということについてなんですけれども、次回、この審査をするときに、医療制度改革に対する意見書の提出を求める請願の審査のときには、きのうの審査の中で国保の関係がかなり中身で入ってきますので、ぜひその保険年金課長になるんでしょうか、その担当の課長にもこの委員会に出席していただきたいというふうに要望していただきたいと思うんですが、よろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":73,"id":"exchange-024"},{"speaker":"鶴副委員長","kind":"質問","question":"この前の「広報しながわ」で、高齢者インフルエンザの予防接種のお知らせをされましたね。「１月３１日までにはがきに住所、氏名、生年月日、電話番号」、ここまではいいんですが、「生活保護受給の有無、障害の有無を書いて、健康課へ」。これは封書ではないわけですよ。その点、今後、これは一応活字になっちゃっているんですけれども、どう対応されるのか、お聞きしておきたいんですが。","respondent":"田中健康課長","answer":"今後とも、そういうことのないように気をつけたいと思いますので、よろしくお願いいたします。","voiceIndex":75,"id":"exchange-025"},{"speaker":"鶴副委員長","kind":"質問","question":"ぜひそうしていただければと思うんですが、もう既にはがきを受理している件数もかなりあるんじゃないですか。どうでしょうか。","respondent":"田中健康課長","answer":"きのう一日で７００通ほどいただいたそうでございまして、職員は保健所、保健センターのほうにも応援を求めてチェックをしています。言いわけになりますが、そういう数があったということで、ちょっとまずい方法を使ったです。","voiceIndex":77,"id":"exchange-026"},{"speaker":"鶴副委員長","kind":"質問・要望","question":"今後は、この事業を１２月１日にスタートさせたいという法案の成立を受けて、どたばたしたこともあるかもしれませんが、ぜひ配慮ある、そういうお知らせというものは心がけていただきたいと、こういうふうにお願いしまして、終わりとします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":79,"id":"exchange-027"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3006#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":20844,"voices":81}},{"id":"h13-20011127-8","meetingId":"h13-cm11","date":"2001年11月27日","dateIso":"2001-11-27","committee":"建設委員会","time":"午前１０時０６分～午後３時３５分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"横山副委員長","kind":"質問・要望","question":"こういったものに入っていなくて、実損が修理費２１万二千某かがかかっているのかということと、いつもここには出てこないんですが、相手方に与えた損害の金額は出てくるんですけど、当方もそれに絡んだ破損というか、それに伴って費用が、修理代というのがかかろうかと思っているんですけれども、いつの場合もそういった当方の損害額というのかな、そういったものは全然見えてこないんだけれども。","respondent":"岩田管理工事課長","answer":"品川区の車の修理代といいますか、損害額は６万3,０００円、そのうち１割を区が補償していただくです。区の修理代が６万3,０００円ですが、そのうち１割が相手方から歳入で入りますので、その差額を区の費用でうちの車を補償するということになります。","voiceIndex":5,"id":"exchange-001"},{"speaker":"横山副委員長","kind":"質問","question":"区の費用でそういうことですけども、この支出は保険、全車両そういった自賠責から出るのか、そちらのほうで手当されるのか、ちょっとそこら辺の仕組みを教えてください。","respondent":"岩田管理工事課長","answer":"区の損害を受けた車につきましては、区は自分の車に対する保険をかけてございませんので、６万3,０００円の修理代のうち、約１割の6,３００円が相手の保険会社から区に支払われますので、その差額約５万7,０００円は区の単費で修理をするという形になります。","voiceIndex":7,"id":"exchange-002"},{"speaker":"沢田委員","kind":"質問","question":"今の関連ですけど、民間の自動車保険というのは、いわゆる任意のほうで、自賠責で任意だと、超えた部分を任意の民間保険がというふうになるんだと思うんだけれども、今回は超えていない、額が低いから超えていないと思うんだけど、結局手続の代行は保険会社のほうに任せちゃうけれども、実態的には自賠責から出ていくんじゃないかと思うんですけど、その辺、いかがでしょうか。","respondent":"岩田管理工事課長","answer":"ちょっと私、これは詳しくないんですが、自賠責保険というのは対人だけだと思ったんですが、ですから、対物関係については任意保険に入っていませんと支払われないという形になります。これは、ですから、任意のほうの保険会社のほうから支払われます。","voiceIndex":9,"id":"exchange-003"},{"speaker":"辻委員","kind":"意見","question":"一つは、この内容なんですけれども、この場合、先ほどの自動車の場合、あえて言えば過失かと思うんだけど、今回の場合、まるっきりどっちなのか。例えば、木が倒れたということですけど、根からボーンと倒れたんだったら、これはおかしいなと、素人目で見れば。例えば、看板が飛んできたというのと同じような感じで、完全にこっちが悪いという感じなのか、その辺をちょっと。","respondent":"松代道路公園課長","answer":"今回の件は根の部分がシロアリ等で根腐れをしまして、根から倒れたんですが、よくそれ以外でも強風等で枝が折れまして、たまたま走行中の車に当たると、そういった場合もこの保険等で対応するといった形をとってあります。","voiceIndex":15,"id":"exchange-004"},{"speaker":"辻委員","kind":"質問","question":"もう一つ、専決処分ですか、これは１８０条の規定ということで、昭和２２年からできてきた議会での指定に基づく専決処分の額ですね、これは全く変わっていないのかどうなのか。ところが、どんどん現在１１万円、１１万円まで、ここまで専決処分として議会で出してわざわざやらなきゃいけないのかという部分から考えると、この辺はどうなんですかね。そういう意味合いなんですけど、この金額はどうなんですか。","respondent":"松代道路公園課長","answer":"下限のほうの金額につきましては定めがないというふうに聞いてありますので、今のところはその都度金額の大小にかかわらず３００万円までは専決処分としてご報告申し上げるという解釈になってあります。","voiceIndex":17,"id":"exchange-005"},{"speaker":"辻委員","kind":"質問","question":"昔からあったんだけど、私も勉強したんですが、たまたま今回まちづくり事業部に関しての専決処分の内容としては、どの辺まで、金額、どういう項目になるんですか。今言った自動車事故、それから枝がおちてきたとか、そのほかにどんなことがあるのか。","respondent":"松代道路公園課長","answer":"損害賠償保険の対象となる損害というところに書いてありますが、私どもが公務として施設、また維持管理、日常の作業等、すべてかかわるものはこの対象にあるものというふうに考えてございまして、私どもで言いますと、道路、公園、それに付随する施設、それに伴った管理用のもの。","voiceIndex":19,"id":"exchange-006"},{"speaker":"辻委員","kind":"質問","question":"そうしたら、例えば滑り台の上からおちたといった場合、どちらが責任どうのこうのというもの。そういうものも対象になる、この辺は結論が出ないと思いますけど、どこまで責任持って、どこまでやっちゃうか。あまりやると、管理管理でガチンガチンになって、行儀よくしないと、公園も遊べないという話になるんだけど、その辺の論議というのは、動いているんでしょうか。","respondent":"岩田管理工事課長","answer":"この線引きというのは、時代とともに変動しておりまして、例えば道路の穴ぼこなんかは典型的な例なんですが、東京のような道路の整備水準が日本一高いようなところのちょっとした陥没と、それから、いなかの地方都市の道路整備があまりきちっとしていないところの同じ穴ぼこでも。","voiceIndex":21,"id":"exchange-007"},{"speaker":"横山副委員長","kind":"質問","question":"内容についてなんだけど、９月１０日の台風というのは何時ごろだったんですかね。というのは、あそこは駐車を当然していて、乗っていたのか乗っていないのかわからないんだけども、時間帯によっては禁止区域だったかどうか知らないし、そのときの状況というか、ここでは、もしそういうことがあれば、やっぱり過失割合というか何かあれなんだけど。それから、そのときの１０日の状況を教えてください。","respondent":"松代道路公園課長、岩田管理工事課長","answer":"当日の発生時刻ですが、９月１０日の８時ごろ、朝の８時ごろです。この東京日世サプライ社員が、商品配送のため、阪急のわきの区道上にとめまして、商品を運んでいたです。委員ご指摘のとおり、この地域は駐車禁止エリアです。例えば、ほかの区道とかお店の前は雪がみんな溶けてしまって何日もたったにもかかわらず、公園の前だけ雪がずっと積もっていて。","voiceIndex":23,"id":"exchange-008"},{"speaker":"横山副委員長","kind":"質問","question":"別に調べてもらわなくてもいいんですけども、過去にそういう報告を受けたんです。というのは、戸越公園、あそこの道路作業所というか出張所のわきのトイレで、そういった事例があったんで、何かやはり民間より役所に言えば何でも対応してくれるというような、何かそんな空気になっていないかという、そういう部分を感じましたので質問させていただいたわけですけれども、結構です。","respondent":"佐藤委員長、田平建築課長","answer":"ほかに。ほかにないようですので、本件を終了いたします。先般、委員会で点検を実施しますというふうに申し上げました。実施期間は９月５日から１１月２２日まで、３階以上の階にキャバレー、ナイトクラブを有する雑居ビルです。４番の点検項目は、階段や扉、非常用照明などです。","voiceIndex":26,"id":"exchange-009"},{"speaker":"辻委員","kind":"質問","question":"ご苦労さまでございました。この件で、基本的な権限とか指導とかは消防署にあるんですか、建築課にあるんですか。今度使い方が、言ってきたように、進入口というのは赤い三角がついているところですよね、ビルなんかのね。どこが実質的には権限を持って取り締まって、改善命令とかいろいろアクセスして督促とかやっていくんですか。その辺の根本的な日常的な仕組みというのをちょっと教えてください。","respondent":"田平建築課長","answer":"そういう格好になります。","voiceIndex":31,"id":"exchange-010"},{"speaker":"辻委員","kind":"質問・要望","question":"今回の新宿のことなんかも、そういうのをやったりしていたけど、向こうは雑居ビルですから、まさしく雑居で、だれが責任者で、だれが直すんだという感じでごちゃごちゃになっちゃうという、これはそういうすきをつかれたというか、油断をつかれたというのが今回の事故の実態なのかなと思う。だれも安全問題は、まさか起こるとは思わないでしょうけどね。これは要望とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":33,"id":"exchange-011"},{"speaker":"上山委員","kind":"質問","question":"ひとつだけちょっとお尋ねしたいんですけれど、今全体の数と品川の割り当て分というんでしょうかね、品川の例えば１人親だと２戸と広報があったかと思うんですけれども、こういう割り当ての比率というんでしょうか、そういう何か比率というのかそうじゃなくて。それから、ゼロというのも、そういうことでそうなっているのか、ちょっとそこら辺を教えていただければと思います。","respondent":"田村住宅課長","answer":"前回もやりましたけど、今回申し込みの空き家につきましては、今後１年間空き家が発生される予定の住宅ということで、これは申込書にも記載していますが、やはり１年間に全体の戸数の中で、空き家の発生等を見込んで空き家がこのくらい発生するだろうということで。","voiceIndex":38,"id":"exchange-012"},{"speaker":"沢田委員","kind":"質問","question":"このことではないんですが、たしか１１月も募集しましたよね。その結果は出ているんでしょうか。申し込み倍率みたいなものは。","respondent":"田村住宅課長","answer":"それと、八潮五丁目のアパート、１１月に都営住宅の地元割り当てとして３戸募集いたしました。申込者が９２名ということで、倍率３0.６倍。それと、やっちゃばの新築住宅ということで、一般世帯用３ＤＫを３戸募集しました。申込者が２５３人、８4.３倍です。","voiceIndex":40,"id":"exchange-013"},{"speaker":"築舘委員","kind":"質問","question":"この多家族世帯ということで、八潮の募集戸数１戸が出ていますけど、間取りが広くないと。６9.２３平方メートル、こういうのは何世帯ぐらいあるんですか、最初からそういうことでつくっていたんですか。普通、都営というとそんなに広いところはないんじゃないかなと思うんですけど、その辺の事情というか、状況はどうでしょう。","respondent":"田村住宅課長","answer":"特に、そのときから想定として、多家族世帯用向けに住宅をつくったというわけではございませんで、やはり、ただ、そうは言っても、例えば１人世帯だと３畳以上だとか、あるいは２人世帯だと１人当たり3.５畳以上だとか、やはりそういう基準が東京都のほうにありますので。","voiceIndex":42,"id":"exchange-014"},{"speaker":"築舘委員","kind":"質問","question":"ですから、１５年ぐらい前に八潮ができたときに、広いところ、ある程度見込んでつくったわけじゃないと思うんですけど、全部が全部そういうふうに間取りをつくったんじゃないと思うんですね。それが結果的にはこういう形で、いい状況だと思うんですよ。","respondent":"田村住宅課長","answer":"やはり、これは住宅建設法で、いわゆる最低居住水準というのが、やはり今回も八期五計に出ているんで、新たなこういったものを計画で最低居住水準、あるいは都市居住型誘導居住水準とありまして、やはり一定の平米面積を確保したものを提供するということで、やはり。","voiceIndex":44,"id":"exchange-015"},{"speaker":"辻委員","kind":"質問","question":"ところが、１３日まで着くかどうかというのはいろいろ問題があって、どうなんだろうと。区内ですから１日あれば着くだろう、あるいは朝早くやれば夕方には着くだろうというのがあるんだけど、ここの辺が非常に不安だと思う。まだ、一般的に消印があるというのは非常にわかりやすいという感じがしますけど、つまり、送るのに、到着するのに配慮して送れというような話だと、すべてどうなんですか。","respondent":"田村住宅課長","answer":"それで今回、６月も若干やり方を変えまして、若干申し込み期間から少し届くまでの郵送期間を見込んで、それで渋谷郵便局まで届くという形にしてあります。ちなみに、区のほうは地元割り当て、先ほど１１月にやったのも消印でやっております。","voiceIndex":46,"id":"exchange-016"},{"speaker":"辻委員","kind":"意見","question":"例えば渋谷郵便局に届けるというのは渋谷郵便局の中に入って、あそこに入れるの。夜間受付でもこうなるわけだ。要するに、手渡しでやるということで。その郵便局の前にあるポストに放り込んでもだめだよね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":48,"id":"exchange-017"},{"speaker":"本間委員","kind":"意見","question":"ここ１年間を振り返ってみて、はだで感じるのは、膨れ上がっているというふうに思いますが、その辺は、倍率の件ですね、どうなっているのか。それと、品川区に係わり合いのある数を今２６戸ということでお示しいただきましたけども、今年１年間を通じて現在までにどれくらい品川のほうの居住としての欠席が出ているのか、ちょっとそれを知ろうかと思って。","respondent":"田村住宅課長","answer":"倍率のほうですけれども、やはりもともと東京都のほうでもやっちゃばのほうで都営住宅を新築するというんで、聞くところによると２３区最後の新築都営住宅じゃないかということで、やはり新築自体がないということで。","voiceIndex":49,"id":"exchange-018"},{"speaker":"本間委員","kind":"質問","question":"実績の部分は東京都の場合、きちっと対応しているということなんですが、実際にどれくらい品川区で１年間で、そういう実績があるという部分での数は把握されていないんですか。","respondent":"田村住宅課長","answer":"全体の募集戸数、例えば１２年度中の全体の戸数で言いますと、空き家単身者全部含めて、品川区内１２年度９３戸です。ちなみに１１年度、まだ１３年度は途中ですから、１１年度の募集戸数で言いますと１０８戸、そういう実績です。","voiceIndex":51,"id":"exchange-019"},{"speaker":"本間委員","kind":"質問","question":"そういう部分の中で、私たちもきちんとした手続も踏みながらということをやるわけですが、非常にせっつかれて、こういう困窮者に対して、どうのこうのという部分がありますので、今お聞きした倍率、あるいは品川区の受け入れの実績等々を見て、そこそこ実績を上げるということはわかりましたけれども、そしてほんとうは、特に都営の部分ですから。","respondent":"田村住宅課長","answer":"ただし、２０年以上居住している世帯は全体の４割を超えて、５０年以上住んでいるという世帯が２４０戸、２６万戸ありますので、対象の分母がもともと大きいですけど、２４０戸であるということで、やはり平均でも１９年ということを考えますと、やはり居住年数がかなりの。","voiceIndex":53,"id":"exchange-020"},{"speaker":"沢田委員","kind":"質問","question":"午後の視察の件で、バスの中での説明でいいんですけど、メモができないのでこちらで聞いてよろしいでしょうか。","respondent":"佐藤委員長","answer":"東京都の職員がバスに同乗して、職員のほうからご説明いただけるというふうな手はずになっているということなんですが、時間がありますから。","voiceIndex":59,"id":"exchange-021"},{"speaker":"沢田委員","kind":"質問","question":"わからなければ、都の仕事ですからあれなんだけど、わからないでいいんですけど。いいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":61,"id":"exchange-022"},{"speaker":"沢田委員","kind":"質問","question":"第二東名だとか、新聞報道ではかなり大きな路線を言われているようなんですけど、この場合に影響がないのかどうなのか。それから、公費というのは、入っているのか入っていないのか。首都高速道路公団の首都高速道をつくるのに、そこらがもしわかったらということと、影響があるのかないのか、現在の動きの中で、そこらをちょっと教えてもらえればありがたい。","respondent":"伊佐都市計画課長","answer":"先ほどご説明ありましたように、午後、東京都首都高速道路公団の職員がバスに乗り込んでいただいて説明をいただくときに、今の件で幾つか答えられない点につきましては、お伝えして、皆さんが集まった場でお伝えした方がよろしいでしょうから。","voiceIndex":63,"id":"exchange-023"},{"speaker":"沢田委員","kind":"質問","question":"新宿線に関しては、都の職員のところで質問したいと思います。3,０００億円の金を注ぎ込んで、本四架橋だって結局税金投入だって昨日の新聞報道で。そういうのも含めて、ほんとうに大丈夫なのかということを私はやるべきなんじゃないかなというふうに思うんですけど、ここでいくら言っても解決するものじゃないんで、気持ちだけ述べておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":65,"id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3708#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":19936,"voices":68}},{"id":"h13-20011127-9","meetingId":"h13-cm11","date":"2001年11月27日","dateIso":"2001-11-27","committee":"文教委員会","time":"午前１０時０３分～午後２時４５分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を9件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"桜井委員","kind":"質問","question":"一般質問でご質問いたしました文化センターについてですけれども、一つまず聞きたいんですけれども、教育次長がセンター条例で、私も問題だというふうに指摘したときに、相談の点については連絡をしてください、電話してくださいと、それで軽易のものは受付窓口に言いますということですけれども、南大井文化センターで、今、区の職員というのはどういうふうになっているかというのを一つ聞きたい。","respondent":"上川内生涯学習課長","answer":"それにつきましては、前にある、それから申請の要項等をもとに同じように対応しているということで、あと複雑なことがありましたらば、こちらのほうに電話をかけて、庁舎のほうに相談をしたりとか、それから、もう少し資料がほしいというようなことについては。","voiceIndex":3,"id":"exchange-001"},{"speaker":"桜井委員","kind":"質問","question":"５館全部見て、５館をもっと、それぞれに問題点をお伺いしたいんですけれども、特に南大井の場合は、荏原文化センターも旗の台も正規の職員がいるんです。だから、南大井の文化センターのそういう今言われた１から７までの中の委託契約というのがそこで完結しないということは、そもそも文化センターのそこの機能が低下しているというふうに私はとるんですけれども、そこはいかがですか。","respondent":"上川内生涯学習課長","answer":"ですから、その複雑なものにつきましては、職員でありましても本課のほうに相談に来る場合もあります。それで、基本的には相談の中で、大きな困った相談というのはないというふうに私のほうは報告は受けております。","voiceIndex":5,"id":"exchange-002"},{"speaker":"桜井委員","kind":"質問・要望","question":"２０００年の、これは課長からの通達なんでしょうか、平成１２年１２月２０日、そちらにありますでしょうか。平成１３年度文化センターの運営管理についてということを、窓口業務を委託するというときに提示されている中身なんですね。それが一つ。でも、本当にそこは昼間でも真っ暗なんですよ。そうであって、職員もあのセンターだけは正規職員がいないわけですから。前段の前提条件の問題と、今の後段の。","respondent":"上川内生涯学習課長","answer":"事務の地域センターのほうにもそういう形でお願いしてありますのでよろしくお願いしますと言ってあります。それから、うちの文化センターの受付の職員にも、そういう話をしたので、利用したいというときはきちんと対応してくださいということを伝えてあります。","voiceIndex":7,"id":"exchange-003"},{"speaker":"桜井委員","kind":"質問・要望","question":"だから、そういうことが、今のお話ですといろいろな要望があるから改善するというお話なんだけれども、そういうことが、例えばあそこの事務室を閉鎖するときにどういう影響があるかということを、少なくとも私は各館ごとにきちんと政策を持つべきだと思うんですよ。この業務を遂行できないわけですから。じゃあ、ここが遂行できない場合はどなたが責任を持つんですか。わからない場合はだれが。","respondent":"上川内生涯学習課長","answer":"それで、そこが基本的に皆さんが交流する場として、お子さんからお年寄りから使っています。それから、その隣に２０畳の和室があるんですが、そこは平日開放して、だれでもがただで利用できる畳の部屋があります。ですから、交流ができないというふうには私ども思っておりません。","voiceIndex":9,"id":"exchange-004"},{"speaker":"桜井委員","kind":"確認","question":"だから、そのことができない場合には、この法的責任というか、昭和建物に責任があるという契約なんですか、どうですか、そこだけちょっともう１回確認したいと思います。それと、もう一つは、だれでも和室が利用できると言うけれども、私が伺ったときには、かぎをかけていたんですよ。それで、何でかぎをかけているんですかと言ったらば、最近いろんな人が来るからかぎをかけているというふうに言うんですね。","respondent":"上川内生涯学習課長","answer":"それもきちんと対応しているということで、正規の地域センターも、文化センターの担当ではございませんが区の職員でありますので、その担当を、小さな施設ですので、それは相互に地域センターの職員も文化センターの部分も見てくれていることは、私も報告を受けておりますので。","voiceIndex":11,"id":"exchange-005"},{"speaker":"桜井委員","kind":"確認","question":"契約について、昭和建物と契約をしているわけですよね。この昭和建物と。今契約内容は言いました。それで、そこの契約について、これができない場合はどなたが責任を持つんですかという、そこをちょっともう１回確認したいんです。どなたが責任を持つんですか。","respondent":"上川内生涯学習課長","answer":"ただし、施設の維持管理とか、通常の緊急対応、トラブルがあったときの緊急対応は、東品川から館長が来るまでの間というか、それは当然区の職員として地域センターの職員のほうが対応するということになっております。","voiceIndex":13,"id":"exchange-006"},{"speaker":"桜井委員","kind":"質問","question":"ことし４月から始められたというところで、スタートに立って半年ですよね。この前だって、例えば利用者協議会に所長なり館長というんでしょうか、文化センター所長か、所長が出るのがいわば前回まで本務だったわけですよ。しかし、ことしからか何かどうもそれは本務ではなくて、何かボランティアっぽく出ていくような話も一部聞いているんです。それは事実じゃないかわからないけれども、聞いているんですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":15,"id":"exchange-007"},{"speaker":"川西委員","kind":"質問","question":"ちょうどいい機会ですので。今、説明がありました南大井の非常勤２名、これはちょっと内容に立ち入って悪いですけれども、再雇用なのか、区の一般募集なのか、管理はどこでなさっているかが一つですね。それから、ついでで申しわけありません、旗の台と荏原は専門職が今までどおりにいるけれども、南大井はわかりました。ですから、どの部分を委託して、どの部分を残していくのかちょっと聞かせてください。","respondent":"上川内生涯学習課長","answer":"非常勤の件ですが、再雇用とかじゃなくて民間の方で、６０歳以上の方をお願いしているというところです。〔「管理は」と呼ぶ者あり〕管理は生涯学習課です。それと、もう一つの部分は、ほかのところも。〔「旗の台と荏原はいいですよ」「東品川」と呼ぶ者あり〕東品川も。","voiceIndex":16,"id":"exchange-008"},{"speaker":"桜井委員","kind":"質問・要望","question":"それで、今後どこの、次回というふうには言いません。正副で運営を任せますけれども、ぜひこの８本については審議を、調査の対象にしていただきたいというふうにお願いしておきたいと思います。","respondent":"藤田委員長","answer":"ただいまの事務事業につきましては、委員会の審査等の関係がどちらもありますので、正副で検討させてください。〔「よろしくお願いします」と呼ぶ者あり〕それでよろしいでしょうか。その他ありますでしょうか。なければ、これから視察に行きたいと思います。","voiceIndex":23,"id":"exchange-009"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4424#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":9179,"voices":24}},{"id":"h13-20011127-5","meetingId":"h13-cm11","date":"2001年11月27日","dateIso":"2001-11-27","committee":"総務委員会","time":"午前１０時０４分～午後３時００分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を34件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"宮崎委員","kind":"意見","question":"説明を聞き漏らしちゃったかもしれないんですけれども、ペデストリアンウェイの位置づけというところで、１枚目の図なんですけれども、今回のところは位置的には大体わかるんですけれども、あとペデストリアンウェイが今回のを入れて５本あるんですけれども、今までこういう計画というのは、私自身あんまり認識なかったんですけれども、以前から決まっていた計画でしたっけ。","respondent":"南雲都市開発課長","answer":"これは、この2)というところにありますように、東五反田地区地区更新計画ということで、平成４年に当時の建設大臣の承認を得た計画ということでございまして、相当昔になりますが、この区の中で都も入りまして委員会をつくってつくった計画で。","voiceIndex":5,"id":"exchange-001"},{"speaker":"宮崎委員","kind":"質問","question":"そうですか。私のほうが勉強不足だったと思うんですけれど、そうすると今の例えば第３地区をつくる関係でいくと、今回報告があったものと、あとは五反田駅から第３地区に通じるものを新たにつくると。たしかここは東急ストアか何かあったところ、そうですよね。このところをずっと道路を通すという計画なんですか。","respondent":"南雲都市開発課長","answer":"これは平成４年当時、大きな構想として打ち出したもので、必ず全部が実現可能ということまで見越したものではございませんので、今回はこの図面でいきますと、下の左側のペデストリアンデッキをつくるということですが。","voiceIndex":7,"id":"exchange-002"},{"speaker":"宮崎委員","kind":"意見","question":"一つ一つの開発の、今回は第３地区なんですけれども、そういう意味では東五反田の計画全体の中の一つなんですよね。ここのところは建物が建つということなんだけれども、人の流れに関しては一体どういうふうに考えているのかなというふうに思うんですけれど、そこら辺のなんで人の動線の確保のところがまだはっきりしないのかというのが、そこのところが解せないんです。ちょっと説明できますか。","respondent":"南雲都市開発課長","answer":"これは将来、構想としてこのときには５本のペデストリアンデッキを設置するという構想が打ち出されたわけですが、実際には全部ペデストリアンデッキという形ではなくて、新しく橋をかけるなりということでも対応できるということで。","voiceIndex":9,"id":"exchange-003"},{"speaker":"宮崎委員","kind":"意見","question":"これは大臣の承認ですよね。そこのところを妨げているものというのは、要するにまだ全部計画がはっきりしないというふうなものというのは、全体の資金繰りだとかそういうところに何かネックがあるのかどうなのか。なおかつ、大臣で承認を受けた計画そのものがまだはっきりしないというのが、なんではっきりしないのかというのがよくわからないんですけれど。","respondent":"南雲都市開発課長","answer":"この地区については、段階的に整備をしていくということで、まずこの第３地区に伴って今回のＤ地区の整備を行いますが、さらに北品川の５丁目第１地区の開発では、この図面の右側のデッキの整備も含めて検討していくということで。","voiceIndex":11,"id":"exchange-004"},{"speaker":"宮崎委員","kind":"質問","question":"今の点はわかりました。将来的にはこのところ、今の図面ですと５,８８２人の通行があると。この２枚目の裏のほうの図面があったんですけれども、これは第３地区のほうが業務棟２棟と住宅棟２棟という計画がありましたよね。その計画での内容ですか。","respondent":"南雲都市開発課長","answer":"この数字につきましては、東口第３地区も含めまして、東五反田地区全体が開発されたときの昼間人口といいますか、就業者、それから居住者のルートを大崎駅と五反田駅の２つで振り分けております。大崎駅方面に向かう人でこのルートを通る人ということで数字を推定したものです。","voiceIndex":13,"id":"exchange-005"},{"speaker":"宮崎委員","kind":"質問","question":"東五反田全体と。そうすると、例えば東五反田２丁目第１地区というのは、当初あそこはオフィスだったんですよね。実際にこういう規模でなく、この計算から言いますと、こういう必要なくなるということも出てくるんじゃないかと思うんですけれども、これは実際、例えば東五反田２丁目第１地区は今の計画ですか。それともその前の計画なんですか。","respondent":"南雲都市開発課長","answer":"これは今現在、東口第３地区の都市計画の協議を行っておりまして、その中でコンサルタントに委託をして推定したものということで、２丁目第１地区については、現在の住宅・オフィスの形状で推定しております。","voiceIndex":15,"id":"exchange-006"},{"speaker":"宮崎委員","kind":"質問","question":"ですから、私はこの全体の交通量の流れで一体この計画はどういうふうになっているのかということを、その中で位置づけをはっきりしたいということで聞いているんです。いや違うんだと。これは全体の計画の中でのアクセスなんだということになったら、この全体の計画の中で実際この流れが５,８８０人というふうな説明になっているんだけれども、どうなんだということなんですよ。感想まで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-007"},{"speaker":"田中委員","kind":"確認","question":"今後のことでなんですが、きょういただいた資料では、１期分、２期分は昨日ご報告ありましたが、その先がまたさらに延びるような格好になっているんですが、これは２期分のものがさらに延長するということの理解をするのかをまず確認しておきます。","respondent":"南雲都市開発課長","answer":"将来ですが、現在は去年行いました基本計画では、環６の陸橋の下の部分までを基本計画で定めたものですが、今後第３地区の開発に伴いまして、この陸橋の下をくぐって、そのあとまた上に渡って第３地区のほうに行くのか、それとも将来は地上の部分だけで行くのかについては。","voiceIndex":19,"id":"exchange-008"},{"speaker":"田中委員","kind":"質問・要望","question":"ちょっと質問させていただきたいんですが、今回１期分の計画ということで昨日ご説明いただいたんですが、今後は２期目、将来３期目もあるかもしれないということで、２期目、３期目が将来的に考えられている中で、先の話なのでわからないとは思うんですが、１期目を受注した企業がやはり２期目、３期目も連続した一体性の構造物と見なしたと考えれば、１期目を受注した企業が２期目。","respondent":"南雲都市開発課長","answer":"あくまでどこの会社でも設計図どおりにつくることができる会社であれば受注は可能というふうに考えています。","voiceIndex":21,"id":"exchange-009"},{"speaker":"田中委員","kind":"質問・要望","question":"構造物と比較はできないかもしれないけれども、大分以前コンピューターシステムを例えば１円で入札してということがあって、一時的な導入は１円で導入はするけれども、その後の拡張だと運用面でその分を含めて採算を考えるなんていうことが以前問題になっていましたが、例えばなんですが、今回は違うとは思いますけれども、１期目で、今後将来２期目、３期目がある中で。","respondent":"西島経理課長","answer":"それからよく新聞に１円とかそういう金額で載りまして、その先のということがよく話題になりますけれども、そういうことも必ずしもないとは言えませんけれども、主に私が見ている範囲で多いのは、コンピューターのシステム関係でそういう要素があろうかと思いますが。","voiceIndex":23,"id":"exchange-010"},{"speaker":"林（宏）委員","kind":"確認","question":"ちょっと確認だけしておきますけれど、戸越幹線と関係ないというけれど、図面でいくと要するに銀六のほうからＪＲ線に向かって戸越幹線が来るわけですよ。そこに横から三木保育園のところとか、それからＪＲのプールの脇のところとかが戸越幹線に入るわけです。戸越幹線のほうがドーッと来たら同じ結果だと思う、それやっても。","respondent":"西島経理課長","answer":"一時的に貯留することによって可能であるというふうに思います。ただ、戸越幹線そのものの流下能力を超えてしまうと、それはちょっと今の段階では即解決は難しいかなというふうには考えています。","voiceIndex":30,"id":"exchange-011"},{"speaker":"林（宏）委員","kind":"確認","question":"そうすると確認しておきたいんだけれど、下水道の管を太くして、何ミリとか対応していく工事をやるのと、空き地というか、公園とかスペースがあったら、あちこちにこういうふうに下水のサイドにそういうものがあったら、そういうものをつくっていっちゃったほうが、時間５０ｍｍ対応をやっているんだといえると思う。経費の面でね。一度そういうこともシミュレーションしてみたらいかがでしょうかね。","respondent":"本多委員長、桑村政策担当課長","answer":"ほかになければ、昨日の補足説明を終了し、予定表の１番に移ります。１枚資料がありますので、これに基づきまして説明させていただきたいと思います。","voiceIndex":32,"id":"exchange-012"}]},{"id":"topic-02","title":"番、(1)の中央防波堤埋立地の帰属","agenda":"番、(1)の中央防波堤埋立地の帰属","exchanges":[{"speaker":"林（宏）委員","kind":"質問","question":"流れは大体わかりました。区長会のほうは部長会でたたいたものをどうかというそういうやりとりだろうと思うんだけれど、部長会でいつごろまでにどういう形をつくろうとか、そういうスパンを考えたというか、そんなような話は出ていないですか。例えばさっき言った都市計画の問題も絡んでいるということから、今年度中にある方向を見つけ出そうとか、そういう期限を区切ったというような話はないんですか。","respondent":"桑村政策担当課長","answer":"今のところ、区長会からは１２月の区長会あたりに協議の方向等をまとめたものを出してくれということですので、最初はとりあえずは１２月になろうかと思います。","voiceIndex":37,"id":"exchange-013"},{"speaker":"林（宏）委員","kind":"質問","question":"１２月に区長会に上げようかじゃなくて、都市計画というよりも、施設建設の先は一応１７年というようなことがあるわけじゃない。そうすると、この問題について例えば１３年度中にはここまで行く、あるいは１４年度中にはここまで行くという、会に上げるとかじゃなくて、このことについていついつという期限が話されたことはないですか。","respondent":"中尾根企画部長","answer":"したがいまして、今回実はいろいろ計画を早く進めるために、その部分だけは帰属と切り離していこうという事務的なレベルが区長会の中ではとりあえず御破算になりましたが、もう一度区長会も１２月中にはというのは。","voiceIndex":39,"id":"exchange-014"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"そういうことの道具に使われるのも嫌なので、その辺は絶えず確認しながらというか、気にしながらやっていただきたい。それからもう一つは、前に部長から話された……。非常に品川にとっては厳しい条件かもわからないんだけれど、そういう実感を上から見て、あの海の上のあそこからあそこだよと言われてもなかなか実感が沸かなかったんだけれど、いけないですかね、こういう考え。","respondent":"中尾根企画部長","answer":"テーブルに着くということだけとにかくうんと言って協議を開始しましょうと。純粋にそれだけの案で次回のところに全５区の区長さんにうんと言っていただける案を要するにこちらとしては練って提示しようと、そういう考えでおります。","voiceIndex":41,"id":"exchange-015"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"さっきの話は別としてしていただきたいし、それから念を押しておきますけれど、施設建設というのはあくまでも５区だけじゃなくて、２３区にとってもという施設ですから、それだけは十分に江東区の区長や部長とはきちんと話をつけていただきたいなというふうに思いますので、お願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-016"},{"speaker":"林（宏）委員","kind":"質問","question":"きのうもお話ししたように、一般質問で何人かの方がペイオフについて品川区の対策ということで質問されて、それはそれでご答弁をいただいていますし、内容的にもわかる。それはそれで品川区としての対応ですから、適切にされていると思う。例えばＡ金融機関に５０億円預けていた。そういうことも含めて品川区はこのペイオフ対策というのをどういうふうにされていくつもりなのか、改めてお聞きをしたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-017"},{"speaker":"林（宏）委員","kind":"確認","question":"第１に、一番最後のところを聞きますけれど、公表しませんというのは、区民は区民で現金を守りなさいよ、預金守りなさいよと、区民には教えませんよというふうに判断していいんですか。一番最後のところだけ確認しておきます。","respondent":"南副収入役","answer":"区民の方には、Ａ銀行が危ないよという形での情報の提供というようなことはまず考えられないかと考えていますけれど、一般にディスクロージャーですとか、そういった情報の提供ということで区民個々人の方がご判断いただけるようなそういうさまざまな情報開示はされておりますし。","voiceIndex":50,"id":"exchange-018"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"これペイオフができると１,０００万円までですよと。実際につぶれちゃったら何で教えてくれなかったのという話が出てこないですかね。それともう一つ、例えばこういう場所で、Ａ銀行からＢ銀行に移りましたねという質問をしたら、イエスと答えざるを得ないでしょう。それから、どうしても金融機関を使わざるを得ないよね。そういうふうに考えておくべきなのかどうか、そこをお聞かせいただきたい。","respondent":"市岡企画財政課長","answer":"そういう意味で言うと、そこで制度融資に入りますけれども、制度融資に関しては、一般の預金とか一般の基金の保全の仕方とは違いまして、やはり引当になっている預託金が区内の事業者のまさに血となっている資金ですから、この預託金をいたずらに引き上げたり。","voiceIndex":52,"id":"exchange-019"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、やっぱりペイオフ対策というのは、最初に言ったようにいろんな方向からメリット、デメリット、それから区民の安全を守る、財産を守るというところから見ていかなきゃいけないというと、単純に公金をシフトして安全になりましたよ、あるいはこれはやむを得ないんですよという部分だけではなくて、やっていかなければいけないと僕は思うし。","respondent":"市岡企画財政課長","answer":"実は、言いわけではないんですが、例えば１０都市の検討会が報告書をまとめるつもりが、この報告書を出すと一人歩きするので恐いので、検討材料だけを出して報告はやめたというような新聞記事がありましたけれども。","voiceIndex":54,"id":"exchange-020"},{"speaker":"林（宏）委員","kind":"意見","question":"この３枚目の都市銀行のグループ分けというか、再編成の表があるんだけれど、これは結構みんなわかっているの。１１行の東京都が許可をしている信用金庫とか信用組合。預けているのは１,０００万円まで保証。例えば単純に１,００１万円預けたら１万円だけ損するということですね。借りている部分はどうなるか。１,０００万円だけ返せばあとは返済はしなくてよい。それを聞いて終わります。","respondent":"南副収入役","answer":"今、仮に１,０００万円を超えて預けておりますと、実際には保険機構のほうから保証されるのが１,０００万円までです。","voiceIndex":56,"id":"exchange-021"},{"speaker":"土井副委員長","kind":"質問","question":"最終的に、これは法律事項でしょうから、元本を保証しませんよというのを議決すれば、元本の保証はなくなるということになっちゃうんじゃないかと。本当につぶれそうだからもう元本は保証しないよという話が要素としてはあり得るんじゃないかなと思うんですけれども、そういうものについてはどんなふうに受けとめたらよろしいんでしょぅか。","respondent":"南副収入役","answer":"一般的に言われている、オーバーパーで買うか、アンダーパーで買うかというような話もありまして、実際にそこでの国債の新規売り出し、それから途中での売買といった市場に国債が流れている量との兼ね合いで、お尋ねのように。","voiceIndex":62,"id":"exchange-022"},{"speaker":"土井副委員長","kind":"質問","question":"国破れて山河ありですから、我々川や山をもらってもしょうがない部分があるんでどうかなと思っただけなんです。ですから、我々が今のところは国債は限られた範疇のこんな形になっているよということなんだけれども、来年３０兆円出されるのか何十兆円出されるのか知らないけれども、それがどんどん仮にいくということになれば、まさしく国が破綻状態になると。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-023"},{"speaker":"塚本委員","kind":"質問","question":"国債に関しても、１０年先、２０年先いろいろあるわけですよね。インフレが来そうだというとになったら一挙にその国債の価値が下がっていくわけですから、ましてや自治体の行きどころがなくて国債にしようとなると、国債というのは非常に不安定なものになるので、僕は国債は基本的には選ぶべきではないとこの際言っておきます。来ていると思うんだよね。","respondent":"市岡企画財政課長","answer":"これも我々の段階での正式な情報ではないんですが、そういうようなことが言われておりまして、実施段階ではこのまま国が各公共団体に任せたよということにはいかないというふうには理解はしています。","voiceIndex":65,"id":"exchange-024"},{"speaker":"塚本委員","kind":"質問","question":"大体こんなものは他国が公金の保全をどうやっているか、ペイオフを先んじて導入した国はあるわけですから、そのスタンダードはこうだよ、アメリカはこうだよ、ヨーロッパはこうだよというのはまだあるはずだと思うんだよね。それが僕らは教えてもらえないものだから、何だか手さぐりで話をしているような感じがする。そのところは皆さん方わかっているの。","respondent":"市岡企画財政課長","answer":"そういうことを今言ってみてもしょうがないので、当面は先ほど出た研究会の報告とか、我々なりの調査研究をやっていくということが基本になるかなというふうに思っているところです。","voiceIndex":67,"id":"exchange-025"},{"speaker":"塚本委員","kind":"質問","question":"うちは安全ですから絶対抜かないでくださいという話、私どもはこうしますから、今までの預金の預かり方と違ってこんなような保証もして保険をかけてこうしますとか、そんな話がどんどん出てきてもよさそうな時期だと思うんだけれど、それも見えてこないというのも何だか妙な。そういう感じは出てこないんですか。銀行側にしてみれば当たり前の話しだ。","respondent":"中尾根企画部長","answer":"今、実際の検討を私どももメンバーですからしているんですけれども、やはり同じように情報がアクセスしてもなかなかつかまらないというのが現実で、それだけ今回についてのこれというのは政府の対応が遅いかなと個人的には思っています。","voiceIndex":69,"id":"exchange-026"},{"speaker":"塚本委員","kind":"質問・要望","question":"８月に立ち上がって、ある意味で１２月が節目だというような話を聞きましたけれども、適当な時期にきちっと大事な、本当に大事な話ですから、基本的なメッセージを伝えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-027"},{"speaker":"田中委員","kind":"質問・要望","question":"その後、国がもし保証できるのであれば、すぐに１,０００万円を引き下ろすような対策をとれるかと思うんですが、それが逆にできないから６０万円までしかすぐには対応できないということで、そうするとその部分を肩代わりするのが他の民間金融機関なのか、自治体なのか、その辺の責任といいますか、責任じゃないんですが、対応の主はどこにあるべきなのかというのがちょっとわからないんですが。","respondent":"南副収入役","answer":"万一、金融機関が破綻したときの対応ですけれど、委員ご質問の中でお話しありましたとおり、当座につきましては普通預金１口当たり６０万円を限度として生活資金等に当てるために仮払いを行うですが、その後資金援助が入った場合は概算払いがされます。","voiceIndex":72,"id":"exchange-028"},{"speaker":"田中委員","kind":"質問・要望","question":"それで今８月から立ち上がったその委員会の中では万が一のときの残りの、資金援助の場合は概算払いということでしたが、ペイオフ対応をされたときの９４０万円までの間の保証に対して自治体といいますか、区が対応するかどうかなんていう検討はされているのかどうなのかをお聞かせいただきたいと思います。","respondent":"南副収入役","answer":"この資金援助方式で清算までされるのにどのぐらいかかるかということ等も含めまして、さらにもう少し私どものほうも勉強をいたしまして、この検討会の中で、先ほど来出ておりますけれど、区民の皆さん。","voiceIndex":74,"id":"exchange-029"},{"speaker":"田中委員","kind":"質問・要望","question":"今その健全状況の中で制度融資という考え方で融資がなされているものは、ペイオフあるいは資金援助対応版として９４０万円がすぐ使えれば倒産を免れたのにという部分の保証というんでしょうか、もう一方制度融資を拡張版的に考えてもいいのかなという思いは少しありますので、ぜひ検討いただけたらと思います。これは要望として。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-030"},{"speaker":"塚本委員","kind":"質問","question":"聞き逃しちゃったので伺いますけれども、今の公的資金の運用の縛りというのは現状であると思うんですけれども、ペイオフについて、一方で安全性が問題が起きてくるわけですから、運用の仕方の縛りが変わるということはあるんですか。こういう運用をしてもいいよと。大体縛りというのはどこから来ているものなのですか。通達等で細かく決まっているんですか。","respondent":"南副収入役、市岡企画財政課長","answer":"地方自治法におきましては、確実かつ有利にというような形で表現をされておりまして、具体的にどういう運用をしなさいというのは、ちょっと今細かいあれを持ってきておりませんであれですけれども。","voiceIndex":77,"id":"exchange-031"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"西郷隆盛とかいろいろ投票のパネルタッチ式に写真が出ているんだけれど、この記事の中でいわゆる実際地方選挙電子投票特例法案というのが月内に成立するだろうと書かれているんだけれど、その辺の見通しだけちょっと聞かせていただきたいんだけれど。","respondent":"木下選挙管理委員会事務局長","answer":"電子投票の特例法ですが、今月の２２日に衆議院を通過しておりまして、１２月９日でしたっけ、末までには成立する見通しだというふうに聞いております。","voiceIndex":86,"id":"exchange-032"},{"speaker":"林（宏）委員","kind":"確認","question":"これができて実際に電子投票をする段取りができてくる。前にこの話が出たときに、だれだかいわゆる投票した側の確認ができない、要するに投票者の確認ができないというんだけれど、これは家ではなくて、投票所へ行って字を書かないで触るという、そういう意味での電子投票で、家でインターネットだとかそういうものまでひっくるめない。通る法案そのものをちょっと簡単に説明してくれますか。次でもいいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":88,"id":"exchange-033"},{"speaker":"宮崎委員","kind":"質問","question":"補正予算で、緊急雇用の対策が出ていたんですけれど、たしかあしたあたりが自治体からの締め切りだったと聞いていたんですけれど、品川区のほうとしてはこの制度はどういうふうに活用しようというふうに考えられているのか、お伺いしたいと思います。","respondent":"桑村政策担当課長","answer":"ですので、出したものでそのまま来るということではなくて、一定の品川区はこの間は２億４,６００万円ぐらいだったですけれども、今回は、もう少し大きいと言われていますので、大きい枠が一定来るんだろうと思っていますけれども。","voiceIndex":94,"id":"exchange-034"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1566#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":31739,"voices":96}},{"id":"h13-20011128-13","meetingId":"h13-cm11","date":"2001年11月28日","dateIso":"2001-11-28","committee":"清掃・リサイクル特別委員会","time":"午前１０時０５分～午後３時０６分","status":"正式会議録","sourceType":"formal","overview":"清掃・リサイクル特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を56件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"土井委員","kind":"質問","question":"そういうものをつくっていくというような動きみたいなものをつくっていかないといけないんじゃないかというふうに思うんですけれども、何かそのようなお話といいますか、議会の果たすべき方向性を決めるべきそういうものの流れ、それが逆の意味で、執行機関側にそういうものの第三者的にきちんとやってくれるところがあって、議会等の議決機関等も聞いてやってくれるということもあるのかどうか。","respondent":"林（宏）議長","answer":"特別区長会の下命事項の一つである清掃事業の安定的な処理体制が可能となる地域ブロックの設定を検討する指定会議体をつくっていく。","voiceIndex":7,"id":"exchange-001"},{"speaker":"土井委員","kind":"質問・要望","question":"議長が受けないというわけじゃないんだけれども、ただ、政策的に決めるという段階のものが上にくっついて、それに従ってやるという流れになりますので、その意味では２３区清掃一部事務組合的には、議会がもっとイニシアチブをとった政策的展開の方向性を打ち出していくというところに、何かもっと欲しいような気がするものですから、ぜひそういう議論をこれから、要望だけですけれども。","respondent":"林（宏）議長","answer":"もちろん言われるように月１回ですから、小回りがきかないというのは事実ですから、計画的に具体的な検討項目を立てていかないとだめだと思うんですね。それはしっかりとやっていきたいと思いますので、いろいろアイデアがありましたらお教えいただきたいと思います。","voiceIndex":9,"id":"exchange-002"},{"speaker":"須藤委員","kind":"質問・要望","question":"きょう議長においでいただいたのは、まさしく今、土井委員がお話になったように、品川区議会として、我々特別委員会をつくって、いろいろな問題をして、１年間でこういうふうにする。そうすると、うちの議長にイニシアチブをとってもらいたい。委員長、そういうふうに理解してよろしいんですか。","respondent":"高木委員長","answer":"それはもう全くそのとおりだと思いますから、議長も品川区を代表していらしていらっしゃる、またこれ、ある種の期間で交代ということも考えられますし、私どもも交代があるわけですけれども、その中で特別委員会をつくった委員、この十数人の認識が、やっぱりそれを。","voiceIndex":11,"id":"exchange-003"},{"speaker":"須藤委員","kind":"質問・要望","question":"先ほど議長もお話があったように、平成１５年度ぐらいから清掃一部事務組合の議会でそういう話を出さなきゃいけないだろうと。そうすると、もう既に品川区議会では、こういうことを清掃一部事務組合の議会に要望してほしいという声を、品川区議会としての総意として上げていって遅くないだろうと思うんです、今からね。これは委員長に要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-004"},{"speaker":"南委員","kind":"質問・要望","question":"ただ、自区内処理というのはそれはそれで大事なことですから、進めていくのが必要なのかなというふうに思うんですけど、現実的にこれから清掃工場建てかえは先ほどの説明で５カ所というふうになってきていて、そのうちの３カ所は数年先になるわけですけれども、これは大体荒川区は土地のめどがまだ立っていないという話なんですが、しかし建てていくというところの予定にはしているということで。","respondent":"林（宏）議長、中山清掃リサイクル課長","answer":"説明の前に、今言われた数量の部分と、それから、最初にお配りすればよかったんだけど、資料をお渡ししますので、説明を受けながら。そういった資源回収がかなりペースを上げて進んだということもあって、単純に言えば少し発生量もごみ量としても落ちた見込みで出てきているです。表の説明だけします。今お話に出てきたように、ごみ量の試算なんですけど、下に説明が書いてあるとおり、Ａは試算ごみ量と書いてあるんですね。","voiceIndex":17,"id":"exchange-005"},{"speaker":"南委員","kind":"確認","question":"このＡのところが処理能力ですから、ごみが出てもこれだけは、何トンは対応できますよという数字ですよね。現実的に、先ほどの課長の説明では、ごみは下回るんじゃないかというふうに予測しているということですよね。だから、それがその処理能力との関係で十分に対応していけるのかどうかというのを改めて確認したいなというふうに思います。","respondent":"中山清掃リサイクル課長","answer":"確かに、その辺の動向を見ながら、今後清掃一部事務組合の共同処理終了後の、逆に言えば各区の計画になっていくということはあろうかと思うんですが、その中でまだ整備されていない工場のありようは、自区内処理が原則と言いながら。","voiceIndex":21,"id":"exchange-006"},{"speaker":"須藤委員","kind":"質問","question":"ですから、そういう区を待っていて自区内処理ができてから、これを清掃一部事務組合について検討するという形になってきたら、なかなか進んでこないと思うんです。やはり、最初のときの１５％のあれができたらばということで考えておいていい。そうすると、この数値よりも今リサイクル、もうどんどんやっていますよね。そうすると、この予定のよりも早い時期に１５％のあれは超えていけると思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-007"},{"speaker":"南委員","kind":"質問・要望","question":"須藤委員の今おっしゃったこともよくわかります。言われたことについては理解はするんだけど、全体的なところを見てどういうふうに考えたらいいのかなというのは、なかなかこの場で判断するのはちょっと難しいところが私自身あるので、だから、そういうふうにとらえていただきたいと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-008"},{"speaker":"土井委員","kind":"質問","question":"今のお話、ある程度わからんわけじゃないけれども、逆の意味で、これを契機に中でまとめてきちっとここで話ができるようにしてもらわなきゃいかんと、そういう意味も含めての話ですから、そうしていかないと、ここの委員会が守旧派的な発言がいっぱい出てくるとどうしようもなくなっちゃうわけで、ここの委員会こそがこうやって初めて議長が発言できる、部長も至るところで発言ができるわけですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-009"},{"speaker":"南委員","kind":"質問・要望","question":"なんかそういうふうに受けとめられちゃったんだったら、ちょっと私の意図するところとは違うので、あえて発言をさせていただいたんですけど、別にストップさせるとかそういうつもりは全然なくて、真剣に議論をするベースがここだという認識は私も持っているし、それがまた大事なことだし、ここの場だけじゃなくていろんな場面でいろんな議論ができて深まっていくことが大事だと思うので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-010"},{"speaker":"堺委員","kind":"質問","question":"今、論議されていることについては私も全く同意見でございまして、平成１７年度でもって、その時点で論議しても始まらない。ですから今がその時期であります。きょうお示しいただいた資料、並びに４１ページに人員について出ていますが、まずお尋ねしたいのは、平成１２年４月１日の移管時点の人員と平成１３年４月１日時点での人員。これ、おわかりになれば。","respondent":"中山清掃リサイクル課長","answer":"その中に、中央工場、渋谷工場という新設工場ができてまいりましたが、実際にはそこの施設管理人員等も新たに、清掃一部事務組合としては採用しないで、結局、例えば大井工場なんかもそうなんですが、もとの人員が１００人ぐらいいたわけですけれども。","voiceIndex":27,"id":"exchange-011"},{"speaker":"堺委員","kind":"質問","question":"同じことをお尋ねして恐縮です。そして次にお尋ねしておきたいのが、事業概要の４６ページの、さっき議長のほうからもこの図を使ってご説明いただいたんですが、お聞きしたいことは、都の職員の真ん中の割愛採用前提職員、そこの欄の項目のところで、身分の切替えというのがありますよね。派遣期間と身分の切替え。ここの絡みというんですか、そこはどうなっているんですかね。そこのところどうなんですか。","respondent":"中山清掃リサイクル課長","answer":"当然、平成１８年４月１日以降については東京都の派遣という形ではありませんから、各区がもし不足を生ずれば、採用していくということを書いているものです。","voiceIndex":29,"id":"exchange-012"},{"speaker":"堺委員","kind":"質問","question":"そうすると、協定当事者で都と各区となっていますが、今のお話で、区が不足を生じれば、その人を引き続き、ただ身分は区になるけれども、採用する。その辺、要するに人が増えるということは人件費につながってくるわけですから、その辺の絡みでいえばどうなってくるのか。","respondent":"中山清掃リサイクル課長","answer":"そこがまた、運営上の見直し等を図りながら圧縮を図っていって、結果的にある年度採用がないということは考えられるわけですけれども、その間にいずれにしても純然たる不足が生じた場合に割愛採用前提職員というのが出てくるということで、平成１３年度はございませんでしたし。","voiceIndex":31,"id":"exchange-013"},{"speaker":"堺委員","kind":"質問","question":"先ほど、可燃ごみの清掃地域処理の中で安定的処理体制を立てると言ったんですね。それは私が理解するには、施設の整備と人員という、人は全く関係ないんです。この安定的処理体制の確立というのはあくまでも施設整備のみのことを指している。人のことは全然言っていません。人的なことをについてはそんなにずれていませんよという理解になるんですか。","respondent":"中山清掃リサイクル課長","answer":"基本的にはごみ処理量と工場の整備のことを言っておりまして、人員の確保のことは言ってございません。","voiceIndex":33,"id":"exchange-014"},{"speaker":"堺委員","kind":"質問","question":"ちょっとお金の件で、資料No.４ですか。あるいはもっと増えるべき数字が何らかの理由があって収入率が減ってますということになってくるのか。これも先ほど廃棄物処理施設整備費の組合費の収入ということですから、組合債を発行しなくては済んだんだろうなと。したがって、収入率が７３％に抑えることができたといっていいのか、１００％の収入率の組合費を見込むべきだったのか。","respondent":"市岡企画財政課長","answer":"２点目の組合債の問題ですけれども、これは私もあれっと思って電話で向こうの財政課長に聞きましたので、まず、先ほど議長のご説明ありましたけれども、投資的経費、工場等の施設整備、あるいはプラント更新にかかる経費がどんどんかかってくるわけですけれども、既に平成１２年。","voiceIndex":35,"id":"exchange-015"},{"speaker":"堺委員","kind":"質問","question":"要するに平成１２年４月１日現在では１,５１３名。条例定数では１,５２３名ですか。それから、これ平成１２年度決算ですから、平成１３年の４月１日現在で１,４７６名でマイナス３７名と。ところが、数値的にはこれだけ予算現額に対して収入済額が、収入率として７３％ですから、２７％のダウンだから、それだけではないような気もします。ところが、国庫補助はこの６３ページの、あるいは資料２でも。","respondent":"市岡企画財政課長","answer":"それで、先ほど清掃リサイクル課長のほうからも、都の時代の実人員、それからそれに基づいた当初の予算編成時の人件費の見込みに対して減ったというお話があったと思うんですけれども、その差でございまして、１０人しか減らなかったから。","voiceIndex":37,"id":"exchange-016"},{"speaker":"須藤委員","kind":"確認","question":"議長から見せてもらった資料３のほうについて、企画財政課長にお伺いしたいと思います。組合債発行額について、先ほど言ったように、清掃一部事務組合が解散された場合、予算特別委員会でも質問してきたと思うんだけれども、もう一度確認なんだけれども、この辺の各区の払い方というか、予算の支出の仕方というのは、都と特別区２３区でどういうふうに考え方を整理されているんですか。","respondent":"市岡企画財政課長","answer":"それで、改めて整理しますと、まず先ほど来、規約のご説明がございましたけれども、共同処理廃止後の財産の帰属等についてはその時点で協議をするという、もうこれは確定した約束になっておりまして、この財産というのは、プラスの財産もあれば、マイナスの財産もあるわけです。","voiceIndex":39,"id":"exchange-017"},{"speaker":"須藤委員","kind":"意見","question":"それに対して今までこうやってきた。清掃一部事務組合になってきたら今度こういう組合債を発行せざるを得ない形で今、建設に入っているわけです。そうすると、一番最初のスタートのときの話が、先ほど言った７００何十億円のあれを手当てしましたよというようなお話があったと思うんだけど、そういうような東京都との関係が今度清掃一部事務組合とはどういうふうにつながっていくのか。","respondent":"市岡企画財政課長","answer":"平成１７年度の間でも、その間に大きな制度改正やどうしても対応できない自体が発生した場合には、財源配分割合の変更について協議を行う。","voiceIndex":41,"id":"exchange-018"},{"speaker":"須藤委員","kind":"確認","question":"今の五つの確認事項というのを１回資料としてこの場に出していただければ、また皆さん方もよくわかると思うんで、それは私があれしたときに区長と知事とみんな立ち会いでという確認事項をやらせてもらいましたので、それは何かあったときに引きずっていったときにまた問題が出るよというのが、何かわからないけれどもというような思いがあったので、そういうものが、組合債。","respondent":"市岡企画財政課長","answer":"それで、ちょうどそのときに当時の区長会の会長だった大田区の西野区長がこの５項目を説明して、最後に都知事石原会長が、これ、都区協議会の会長という意味ですが、「今、西野区長から発言がありました５つの点については。","voiceIndex":43,"id":"exchange-019"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"先ほどいただいた資料どおりなのか。自分はちょっともらった資料の中で、工場がないブロックは第２ブロックですか、あそこなんか全然採用できなくなってしまうんではないかなというのが一つあったのと、それからもう一つ、ブロック化というか、共同処理が廃止になる、平成１７年度末ありますけど、それは共同処理の廃止であって、清掃一部事務組合の解散がイコールではないという部分がまだありますよね。","respondent":"中山清掃リサイクル課長、市岡企画財政課長","answer":"先ほど、委員長のほうから配られた資料の４と入ったものが、後で配られている、この２枚目に清掃工場整備計画の検討案というものがあります。その限りでは、文字どおりの解散ではないんですが、先ほど申し上げたとおり、適債条件を持っている施設の引き継がれる主体に債務が承継されると、こういう理屈になります。","voiceIndex":46,"id":"exchange-020"},{"speaker":"鈴木（真）副委員長","kind":"質問・要望","question":"今、最初の件の、この表は見ていたんですよね、整備計画。それから、組合債の件でもう一回お聞きしたいですけれども、先ほどちょっとお聞きしました、財調総額で１兆６,０００億円ぐらいという数字がありましたよね。もう一個、最後、自治会館。平成１７年に入るんですか、平成１７年４月。そうすると、解散するまで１年間という状況がほんとうにいいのかどうか、そこら辺も教えていただきたいと思います。","respondent":"中山清掃リサイクル課長、市岡企画財政課長","answer":"簡単に、先ほどの焼却能力率の数値の関係ですけれども、ごみ量の減があっても満たされない部分というところは、実は一番大きな影響はプラント更新及びダイオキシン対策の影響で。財調は、財源の配分割合を決めておりますけれども、来年度も非常に税収の見込みは厳しい状況でございまして、全体が減れば、幾ら５２％確保していても、必要な経費がすべて財調で算定しきれるかどうか、今。","voiceIndex":49,"id":"exchange-021"},{"speaker":"須藤委員","kind":"提案","question":"先ほどご提案させていただいたスケジュール的な問題で皆さんと整理をしていただきたいのですけど、最終的にこの委員会で、こういう方向性だよというのを調査に持っていきたいという思うんですが、それはスケジュール的に、あと１月、２月の２カ月ぐらいなので、どんな手順で、先ほど出たものについて対応していくのかということをちょっとお話ししていただければ、また各会派のメンバーで。","respondent":"高木委員長","answer":"本特別委員会の残りの期間というものは、これはおわかりのとおりですから、その中で清掃一部事務組合の問題点について特別委員会でいろいろ審査をいたしまして、意見なり要望なりいろいろ集約するのをどうするかというようなことについて、ご意見がありましたら。","voiceIndex":54,"id":"exchange-022"},{"speaker":"土井委員","kind":"意見","question":"今お話がありましたけれども、私たちが議会として、この特別委員会をつくって審議をしていく、審査をしていくということの大目的は何であるかということになると、それは最終的に平成１７年度の特別区への移管といいますか、が完了するというか、清掃一部事務組合が解散、言葉はどうであるかはともかくとして、この部分を成就するということが大前提なんだと。それに向かって、私たちは何をやっていくのかと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":56,"id":"exchange-023"},{"speaker":"鈴木（真）副委員長","kind":"提案","question":"そういう問題をこの委員会としてどう考えていくか。清掃一部事務組合に関することがこの委員会の項目の中に１つ入っていますから、その分だけは皆さんで、例えば各会派ごとに、清掃一部事務組合はどういうやり方で進めていくべきだというような意見をまとめておいて、またさらにそれを持ち寄って、この委員会の中で詰めていったらどうかなというのを、これは個人的にです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":57,"id":"exchange-024"},{"speaker":"南委員","kind":"質問・要望","question":"だから、議長会なり清掃一部事務組合のその会の中で、私たち品川区議会としても、区民の意向も反映した意見というのは、そういう土台はできているわけだから、あえて、須藤委員がおっしゃるそこのところが、今までのいろいろな委員会運営の中の範囲で私はいいんじゃないかなというふうに思っているので、プロセスを決めてやっていくという、そこのところがどういう思いなのかというのは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-025"},{"speaker":"須藤委員","kind":"確認","question":"そういう委員会であってほしいと思うんです。そのためには、副委員長がお話しのように、各委員の中で、こういう考え方がありますけど、１月に出してもらうのか、２月に出してもらうのかということを今お尋ねしているので、そこで集約できれば一番いいし、集約できない分は、大多数はこうですけど、少数意見はこうであるというようなことをまた議長にお聞きして、議長としての考え方を整理できると。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-026"},{"speaker":"南委員","kind":"質問・要望","question":"ただし２３区清掃一部事務組合の中で、自分の区に自区内処理すると言いながらも、できないで困っているという、そういう区も含めて２３区のところで話し合うわけだから、そこの一致点がないと、いくら品川がこうやってほしいという意見を表明して、議長に頑張っていただいたにしても、なかなかそこのところというのは、２３区レベルでは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-027"},{"speaker":"須藤委員","kind":"質問・要望","question":"それが１月に、２回やります、３回やりますと、了解を求めればできるだろうけれども、常識的には１月に１回、２月に１回しかできないわけですから、ある程度のスケジュール的なものを委員長、副委員長で考えていただいて、何も今ここで答えを出さなくもいいですから、後で各会派に、１月の何日ごろの委員会までにとか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":61,"id":"exchange-028"},{"speaker":"土井委員","kind":"確認","question":"３月にはもうまとめなきゃいかんものですから、まとめのやつを１回やるためには、あと２回のときにそれを出さなきゃいけませんので、どのようにいたしましょうかということですから、次回までにどう議論をするかということはともかくとして、そこら辺の気持ちをそれぞれの会派で持ち寄って、最後は総意にできるものは総意にしましょうということだろうと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":63,"id":"exchange-029"},{"speaker":"中島委員","kind":"確認","question":"私自身が、清掃一部事務組合というものがよくわからないのでここへ望んできたんです。先ほどのご説明の中にも、区民一人頭５,０００円のお金が支払われている。そういう意味で、先ほど、五つの確認事項を今度提出してくださるということだし、そういうことも合わせて、私たち自身がもっといろいろ検討をしていく必要があるなということを感じております。","respondent":"高木委員長","answer":"さっきの企画財政課長の資料などもいただいて、いろいろ考えたいと。ほかにございませんか。","voiceIndex":65,"id":"exchange-030"},{"speaker":"北野委員","kind":"質問","question":"それで、１月はあるんですけれども、２月は清掃リサイクルの委員会ってないですよね。そうすると、もう３月になってしまうというところでは、やはり１月時点で、ある程度の、現時点での方向性でもいいですから、各会派が持ち寄って、この場で議論をして、３月時点でまとめる方向にスケジュール立てをしていったほうがいいのではないかなと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":67,"id":"exchange-031"},{"speaker":"南委員","kind":"質問","question":"ちょっと聞きたいのは、２３区の清掃一部事務組合の審議状況で、３月までに出さなくてはいけないという、そういう趣旨の発言をされていらっしゃるので、その辺との進捗状況の関係を知りたいんですけれども、どんなですか。違う。別に時期は３月に限らなくていいのであれば、それはそれでいいんですけど、私の疑問は解けるんだけれども。何を言いたいかというと、この委員会の任期が来年の５月までですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":68,"id":"exchange-032"},{"speaker":"南委員","kind":"質問","question":"だから、例えば自分の都合で何月何日に来てくれというふうに出すんだろうと思うんですけれども、相手との関係で、そこの調整というのは、ファックスの場合はどうなるのかというのが一つと、それから、年間７万件と書いてあるんですが、今までの実績というのは、大体どのぐらいあるのか、ちょっとそんなことを教えてください。","respondent":"中山清掃リサイクル課長","answer":"正式なお申し込みでなくても、やはりオペレーターとしては一定の時間を割いて対応しなければいけませんので、結局この見込みの件数によって、オペレーターの配置、人員が決まってくるということで、目安の数字で示しているものです。","voiceIndex":75,"id":"exchange-033"},{"speaker":"南委員","kind":"質問","question":"オペレーターとなると、これは区の職員じゃなくて、どこかそういう機関に委託をしてやるんじゃないかなと思うんですけど、参考のために、どういうところがあるのかちょっと教えていただければと思います。","respondent":"中山清掃リサイクル課長","answer":"新年度予算にかかってくるわけですけれども、コールセンターを運営する専門の会社というものがありますし、あとは開発プログラムとの関連がありますので、受付だけを全く別の機関を使うというわけにはいきませんので。","voiceIndex":77,"id":"exchange-034"},{"speaker":"南委員","kind":"質問","question":"全部聞けばよかったんですけど、例えば、今自分でリサイクルショップ「リボン」に持ち込むんですよね、今の粗大ごみは。その辺ちょっと、どういうふうになるのか教えてください。","respondent":"中山清掃リサイクル課長","answer":"リサクルショップ「リボン」というのは、これは粗大ごみとは別に、リサイクルショップ「リボン」に直接お電話をいただいて、これは委託販売ですから、いわゆる値決めもしまして、それによって、そのうちの２割の手数料をお店に歳入し、１店当たり、極端に言えば。","voiceIndex":79,"id":"exchange-035"},{"speaker":"堺委員","kind":"意見","question":"恥ずかしい話で申しわけないんですけど、コールセンターを開設し、プログラムを開発して、そういう業者に委託するということですが、要するにお尋ねしたいのは、受付センターというのは、どこに開設するのかという……。","respondent":"中山清掃リサイクル課長","answer":"逆に言えば、区内とも限らないということですけれども、できるだけいろんな場面に、柔軟に対応できるような場所に確保していくほうが、区のセンターとして運営していく上ではやりやすいということは考えております。","voiceIndex":81,"id":"exchange-036"},{"speaker":"堺委員","kind":"質問","question":"民間の建物の中で、場所は区内とは限らないという、ただ、いろいろ利便性などを考えると、区内にしたほうがいいような気もするんですが、受付センターの概要の一番下の中でよりきめ細やかな対応、区リサイクルショップでの大型家具販売の案内などを区の施策を踏まえた受付を行う、こういうことから見ても、やはり区内のほうがいい。ただここは受付するだけなんですか。具体的な業務内容を。","respondent":"中山清掃リサイクル課長","answer":"根元におきたいというのは、あくまでも希望的に言っていることでございまして、市内局番で電話が通じればどこでも設置が可能なものです。","voiceIndex":83,"id":"exchange-037"},{"speaker":"堺委員","kind":"質問","question":"電話を受けるだけでいい、それだけのスペースがあればいいわけでしょう。となれば、区の庁舎の中でも可能、あるいは清掃事務所とかそういうところでもいいんじゃないでしょうか。","respondent":"中山清掃リサイクル課長","answer":"であれば、区の施設を使えば、いろんな意味で、例えば場所代も含めて合理的なのではないかということを含めてのご質問かと思いますが、現実には、こういうマンパワーを確保する際に、品川区単独、単独と申し上げているんですけど。","voiceIndex":85,"id":"exchange-038"},{"speaker":"堺委員","kind":"確認","question":"わかりました。最後に確認したいのは、スケジュールと進捗状況の一番下に、環境清掃事業部ホームページとリンクさせる。これは、受付センターで受け付けたものとリンクさせるということですか。","respondent":"中山清掃リサイクル課長","answer":"電話によるオペレーターの受付が先ほど来申し上げている、コールセンターで人材を複合的に確保できるスペースであるという説明でありまして、受付センターという言葉としての機能には、先ほど来申し上げいるファックスだとか、インターネットによる受付も考えているわけですが。","voiceIndex":87,"id":"exchange-039"},{"speaker":"北野委員","kind":"質問","question":"今の話だと、インターネットと電話とファックスと３つ連動したら、そのときにすぐ回答は出るんですか。ファックスの場合は、後から連絡というなんですけど、インターネットと電話の場合は、すぐ回収というのが、コンピューターの中でサーバーでやって、すぐ回答が出るという形になるんでしょうか。","respondent":"中山清掃リサイクル課長","answer":"ただ粗大ごみの場合はシールを張って出してもらえればいい話ですから、基本的に都合悪くないはずなんですけれども、一応、何月何日になりますよということの案内はその場でいたしますし、インターネットの場合の画面設定、もう一回これはプログラムを最終で詰めますけれども。","voiceIndex":89,"id":"exchange-040"},{"speaker":"北野委員","kind":"質問","question":"ファックスで、希望日があれば希望日をこっちのほうで入力してやるか、事前に予定日を入力して返事を出すという形になって、大体その期間というのは、時間というのはどのぐらいですか。電話の対応が、東京都ではなかなかかかりにくいという対応から端を発して、この品川区独自の粗大ごみの受付というのを開始したと思うので、そういうところでサービスとしてどういうふうにしているのか伺いたいんです。","respondent":"中山清掃リサイクル課長","answer":"説明がまた不十分で、希望というようなことを申し上げてしまったんですが、実際には、各地区ごとに、月の中で言えば、どういうふうに収集するというのをプログラムの中に放り込んでおりまして、これはごみの収集と違って。","voiceIndex":91,"id":"exchange-041"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"やはり２３区の共同センターでは、品川区のこういうふうなやり方というのは、やっていただくことができないということで、改めて別なところにというふうなことになるということなんでしょうか。委託費は今までの委託費と比べて、今度の委託費というのはどうなるのかということについてもちょっと教えてください。","respondent":"中山清掃リサイクル課長、野本環境清掃事業部長","answer":"２点目のコストの面ですけれども、これは単純に考えれば、本来、全体で分担したほうが、コスト的には、スケールメリットは安くなってしかるべきだという考え方もあるわけなんですけれども、できるだけ利便性を図りながら。今の中山清掃リサイクル課長のほうでご説明しましたように、立場上、あまり具体的な話ができないんですけれども、今の話というのは、このままですと、まだ皆さんおわかりにくいんじゃないかなと思います。","voiceIndex":95,"id":"exchange-042"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"今の説明はわかったんですけど、今までの仕組みがよくわからないんです。２３区共同センターというものは、今度委託するような民間のところと違う……、どういうところになるんでしょうか。よくわからないので教えてください。","respondent":"中山清掃リサイクル課長","answer":"したがって、そういう中２階のような組織が今回でなくなり、区との関係になっていくので、そこでコストの削減を図ることと、先ほど申し上げたように、逆に離れることによる共同開発的なスケールメリットを出すことで、さらにコスト削減を図ろうということをしているです。","voiceIndex":98,"id":"exchange-043"},{"speaker":"須藤委員","kind":"意見","question":"今の部長の話でよくわかりました。でも、今のお話で、電話番号５７１５－１１２２、品川区ではないところの電話番号を見れば地域的なところもわかるしね。一つ一つ、ここで頑張っていただいているというのを見せていただいて、いろんなほかの自治体との関係もあるから言えないところもあるだろうけれども、そういう意味では頑張っていただいているというのを一つ見せていただいたので、ありがとうあります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":100,"id":"exchange-044"},{"speaker":"南委員","kind":"質問・要望","question":"そうすると聞き取れない場合があって、もう一回やり直さなくちゃいけないということが出てきて、すごく嫌だなという経験を何回か、皆さんも１回か２回はあると思うんですけど、そういうふうな対応にはならないんじゃないかと思うんですけど、改めて確認しておきたいし、そういう対応というのはぜひやめていただきたいんです。高齢化社会になりますから、その辺の配慮は十分にお願いしたいと思います。","respondent":"中山清掃リサイクル課長","answer":"オペレーターによる受付ですから、機械が受けるわけではございませんので、必ず直接、職員が受付をいたします。それに向けてトレーニングを開始するです。","voiceIndex":101,"id":"exchange-045"},{"speaker":"飯沼委員","kind":"質問","question":"だからこれを活用していただくために、どういう周知をして、広報に載ったんでしょうかね、ちょっと私、よく見ていなかったんですけど、周知と清掃事務所の職員の方が配布してくださったということで、大変ご苦労があったと思うんですけれども、今後これをどういうふうに活用していくという思いがあると思うんですけれども、その辺をちょっとお伺いをしておきたいと思います。","respondent":"中山清掃リサイクル課長","answer":"ただ、どうしても配布としては手渡しが難しゅうありますので、一斉に配布するようポストの中に入れてしまわざるを得ないということもありますので、周知としては「広報しながわ」、またＣＡＴＶホームページ等でもご案内していくことを考えておりますので。","voiceIndex":107,"id":"exchange-046"},{"speaker":"飯沼委員","kind":"質問","question":"ぜひ町の話題になるというか、再利用が広がるような役割を果たしてほしいなと思いますので、今後、いろいろな周知の仕方があると思うので、その辺をお願いしたいのと、基本的なことで、費用の問題で、企画から制作に当たって、どのぐらいかかっているのかなと。","respondent":"中山清掃リサイクル課長","answer":"コストですけれども、当初の予算からすると、実は半額以下で済んだわけですけれども、それでもコストしては約４６０万円ですので、１８万部で割り返しますと、二十六、七円ということになろうかと考えています。","voiceIndex":109,"id":"exchange-047"},{"speaker":"飯沼委員","kind":"意見","question":"さっきのご周知のほう、よろしくお願いしますというお話をしたんですけれども、廃棄物減量推進委員の方々の研修や何かに、すごくいいものだなと思うので、ぜひ活用してほしいこと、町の皆さんの、そういった面での声を受けてほしいなと考えています。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":111,"id":"exchange-048"},{"speaker":"須藤委員","kind":"質問・要望","question":"これ自体は、清掃リサイクル課の皆さんがいろいろお考えになったけど、もとの発想は、海外へ議会の調査団が行かれて、その報告をもらってがベースだというように思うんですが、その辺の関係が１点と、それから、平成１５年の３月で終わって、年度末ということで、また平成１６年になったらどうなるのかな、何か中途半端なところで終わってきているので、その辺が……。","respondent":"中山清掃リサイクル課長","answer":"いろいろ議論したのですが、そのエリアを再度つくり直して配るというのも、非常に資源のむだということも考えて、実は、平成１５年４月については、作業が変わることもにらんだ１５カ月というふうになっておりますが、ただ。","voiceIndex":112,"id":"exchange-049"},{"speaker":"北野委員","kind":"質問","question":"だから、集まったというところで、モデル号というのが、結構、大井第一地区なんかも、リサイクルにもモデルにしているというのがあって、環境教育の中のいろんなのが出てくると思うんですけど、こうやって載るということが、各家庭に配られたときに、子供たちが、じゃ、応募したら載るというところで、またカレンダーを見る感覚も違うでしょうし、ごみに対する意識というんですか。","respondent":"中山清掃リサイクル課長","answer":"ちょっと正確な件数は手元にないんですが、約３００件ほど出てきたと考えています。私ども環境清掃事業部の職員のほうで、ある種の選考といいますか選びながら、これはその中で割合人気の高かったものを入選ということで選ばせていただいたものです。","voiceIndex":114,"id":"exchange-050"},{"speaker":"北野委員","kind":"質問・要望","question":"ありがとうございました。これでリサイクル、ごみの問題意識も深まると思うので、よろしくお願いしたいと思います。それと、これは今後の要望になるかと思うのですが、平成１５年４月以降、またここの内容を、月々のメインの内容を整理して、いろいろな形を考えていかれるのかなと思うんですよね。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":116,"id":"exchange-051"},{"speaker":"南委員","kind":"質問・要望","question":"一つ伺いたいのは、子供たちの教材として活用してもらえたらなというふうにも思っているんですけど、字が細かいとかいろいろありますけれども、しかし、考え方として、せっかくこういうものができたわけですから、現在思っていらっしゃることを伺います。","respondent":"中山清掃リサイクル課長","answer":"何分最初につくったものですから、さまざまのご意見、これから配布した後、区民の方からもご意見も出ようかと思いますので、継続的に改善をして、よりよいものにしていきたいとは思っております。","voiceIndex":117,"id":"exchange-052"},{"speaker":"藤原委員","kind":"質問","question":"もう１点は、ビデオの中で司会の女性の方が、「事業者の方」という言葉を使っておりましたが、これを「区民の方」と変えれば、すごくなじみがよかったので、今見せていただいたビデオは事業者向けだと思うんですけれども、「事業者」という言葉を「区民」に変えれば、一般の人たちにも見ていただけるような、あれをベースにすごくいいものができると思うんですけれども、そういうお考えはありますでしょうか。","respondent":"中山清掃リサイクル課長","answer":"したがって、やはり映像でこういうものを説明したほうが非常にわかりやすく聞けるという声もありましたので、考えていきたいとは思っておりますが、補助金が今回適用になりましたけれども、それ以上にコストがかかるものですから、効果をにらみながら、委員がおっしゃるような。","voiceIndex":124,"id":"exchange-053"},{"speaker":"飯沼委員","kind":"意見","question":"貸し出しのビデオが１５本ということで、この辺の根拠というか、対象の事業所、前にも聞いたんですが、忘れちゃったので、もう一回、どのぐらい件数があるのかと、あともう一点は、条例に基づく義務のところで、ここにも書いてありますけれども、管理責任者の選出とか、計画書の提出とか、あと講習会の参加状況というのが進んでいるのかどうか、その辺をお聞かせください。","respondent":"中山清掃リサイクル課長","answer":"その他の事業者への対応ですけれども、基本的には、委員おっしゃるように、一定規模以上の事業所につきましては、再利用計画書の提出、廃棄物の再利用計画書と廃棄物管理責任者の選出というものをお願いをして、毎年１回、４月に文書を発送して、両清掃事務所のほうで該当事業所。","voiceIndex":126,"id":"exchange-054"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ありがとうございました。２５０万円もかけて使ってつくったということなので、ぜひ活用していただきたいなと思いますが、冊子みたいな感じで、多少お金がかかっても、有料の形で買っていただくみたいな感じの普及というのは不可能なんでしょうか。広く見ていただきたいなと思うんですけれども、その点はいかがでしょうか。","respondent":"中山清掃リサイクル課長","answer":"確かに物によっては、区の中でも有償配布物はありますから、考え方としてはあろうかと思うんですけど、ただ、やはりこういう身近なごみサイクルに関することをお伝えするとなると、逆にできるだけコストも圧縮しながら。","voiceIndex":128,"id":"exchange-055"},{"speaker":"北野委員","kind":"質問・要望","question":"結局、貸し出しをしたりしますけれども、品川区の各部署にいろんなビデオがありますよね。環境の問題とかを取り扱った、それが結局、区民の目に触れないで、長い間年月を経て保管されていたりすることもあるわけですから、やはりそのとき限りではなく、継続的に使われるような形をとっていただきたいなと思うんですけど、いかがでしょうか。","respondent":"野本環境清掃事業部長","answer":"今のはごもっともなご質問だろうと思うんですけれども、たまたま今年、ＩＳＯ１４００１を取得させていただいたということで、再々お答えさせていただいていますけれども、来年度は環境計画の作成に入ってまいります。","voiceIndex":130,"id":"exchange-056"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5652#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=13&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":67657,"voices":134}},{"id":"h13-20011129-16","meetingId":"h13-cm11","date":"2001年11月29日","dateIso":"2001-11-29","committee":"街づくり特別委員会","time":"午前１０時０６分～午後３時０２分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を31件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の密集住宅市街地整備促進事業の推進について（その３）","agenda":"の密集住宅市街地整備促進事業の推進について（その３）","exchanges":[{"speaker":"三上委員","kind":"質問","question":"今説明をいただいた中で、一つ、前回と違っていたのは、前回は懇談会メンバーが敷地内に１名いるという話をしていたんじゃないでしょうか。今のお話だと、だれもいないという、ちょっと違っているんですけれども、どうなんでしょうか。","respondent":"浜脇住環境整備課長","answer":"申し訳ございません。私どもがちょっとあわてておりまして、隣地のときにはいたんですが、その隣地の方を数えてしまって、１名という話をしたけれども、中には０です。今日お話しした、懇談会の参加者は１０名中０です。","voiceIndex":5,"id":"exchange-001"},{"speaker":"三上委員","kind":"意見","question":"ますます心配になってくるというのは、全体として8.１haという地域の中で懇談会メンバーといわれる、要するに、この地域をどうしようかということを取りまとめていく、その中で1.２haの１４０世帯の人たちの問題が、その地域に住んでいない人たちの意見でまちづくりが進められるということが、果たしていいのかどうかと思うんです。","respondent":"浜脇住環境整備課長","answer":"８ha全部が規制がかかったり、緩和がかかったわけではございませんけれども、そういう全体的な話としてはいい話だなと、こういうふうに私どもとしては、その会の話し合いとしてはこういうふうな結果が得られたというふうに思って、今回のご報告になったわけです。","voiceIndex":7,"id":"exchange-002"},{"speaker":"本田委員","kind":"質問","question":"非常に大事なことなんですね。しかし、なかなか全体としてはこういう数字しか出てこないというところに隘路があるように思いますので、その辺は十分に配慮して、問題が起きないように、地区計画という法律の網がかぶさりますと、これは簡単にとれませんので、かぶせる前に十分時間をかけて論議をするということが大事だと思いますので、その辺をよろしくお願いしたいと思いますが、いかがでしょうか。","respondent":"浜脇住環境整備課長","answer":"私も最初に申しましたとおり、私どもとすれば、そういう懇談会の会議の中で一つの方向性を出し、地元の説明もしたつもりですが、委員の方々から出ておりますように、そこまでの心配をして、話をしたというふうにはならなくて、その辺は周知不足と言われれば。","voiceIndex":13,"id":"exchange-003"},{"speaker":"藤田委員","kind":"質問・要望","question":"ですから、これはきちっと、あなたの資産に係わる問題です。ぜひ出席してくださいというぐらいの、ちょっとインパクトがあるような文面と、百何名の家ですから、ポストにポンと入れるだけでなくて、できれば１軒１軒行って、手分けして行けば１人１０軒ぐらいで終わっちゃうと思うんですよ。ですから、そういう形でぜひ出席してくださいと。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":15,"id":"exchange-004"},{"speaker":"伊藤副委員長","kind":"質問","question":"いろいろ話が出ておりますので、重ならないようにしますけれども、合意形成ができていないということは、いつもの区側の回答なんですね。聞きたいのは、時間の設定とか、ＰＲの方法についてとか、考えているんですかということを聞きたいんです。例えば夜７時からやるのではなくて、時間をずらしてやるとか、回数も工夫をするとか、そういうことは考えているんですかということをお伺いしたいんです。","respondent":"浜脇住環境整備課長","answer":"普段の平日の昼間というだけでなくて、土・日もどうだろうかと、このような話も含めてご相談をしながら、出席が可能になる方向でやってまいりたいと考えています。","voiceIndex":16,"id":"exchange-005"},{"speaker":"伊藤副委員長","kind":"意見","question":"もう話が随分伝わっていると思いますから、まとめていきますけれども、少し前に八ツ山アンダーパスの件の話がありましたでしょう。来ない方をどう出していくかということが、各委員もそういう意見だと思いますから、来ない方をどう出していくかということに焦点を当てて、ぜひ周知方をしていただきますように、改めてお願いしておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":18,"id":"exchange-006"},{"speaker":"宮崎委員","kind":"意見","question":"１点お願いしておきたいんですけれども、そういう意味では今が正念場だと思うんです。そのことは、そういう体制なども含めて、課長というよりも、部長、もっと上のほうになるかと思うんですけれども、配置をするということも検討をしてもらったほうがいいんじゃないかなと思います。","respondent":"山室住宅指導担当部長","answer":"我々ももとより、参加率を上げる工夫を考えなければいけないなというふうに考えておりまして、当然まちづくり事業部、担当する私、それから、担当課を含めて説明会の体制については検討をしていきたいというふうに考えております。","voiceIndex":19,"id":"exchange-007"},{"speaker":"石田委員","kind":"質問・要望","question":"今お話を伺っていて、周知の問題ももちろんあると思うんですが、今お話があったように、この地区計画というのは、例えば２３区でも斜線を検討をするというのにとっては、一番だというお話で、これは内容的には非常に一石を投じた内容であって、密集市街地の中では非常に、私は平米数の問題は反対だからあれだけど、斜線からいけば、非常にいい方向性の地区計画だと思っているんです。全員同意は無理でしょう。","respondent":"浜脇住環境整備課長","answer":"ですから、最初の地区計画自身の発意はまちづくり懇談会の委員の方々ですが、私どもはそれをなるべく皆さん方の総意となるように努力をしたつもりですが、参加の数という面では少なかったというふうに考えておりますので、情報収集ということは。","voiceIndex":21,"id":"exchange-008"},{"speaker":"石田委員","kind":"意見","question":"まちづくり懇談会の人には、その意見を集約してもらって、上がってきたものを、我々はそこで承諾と思って動きますとか、そういう明確なものを、これからあと日にちがあるわけで、そこら辺の流れを計画的に考えていかないと、いつまで経っても、今の答弁で、それでは人が少ないじゃないかとか、周知はどうしたんだとか、周知なのか、承諾なのかというところがあるわけで。","respondent":"山室住宅指導担当部長","answer":"もう一つは、説明会に出られなかった方に対しては、例えば役所の担当者名とか、時間等は当然付して、今までもやっているところですが、問い合わせ等に一定の期間応じるような、そういったこともさらに徹底するとか、いろいろな工夫をして。","voiceIndex":23,"id":"exchange-009"},{"speaker":"上山委員","kind":"確認","question":"先ほどほかの委員からも出されておりましたけれども、５０cmのセットバックの問題とか、今後で言えば、高さ制限１０ｍ、敷地面積の最低限度６０m2にするとか、緩和の点で言えば、繰り返しになるから申し上げませんけれども、斜線の問題とか、いろいろありますよね。ちょっと私は勉強不足で申し訳ないんですが、もう一度そこのところを確認したいんです。","respondent":"浜脇住環境整備課長","answer":"当然６０m2というのは何なんですかという話がございまして、６０m2というのは、今持っている方は別ですけれども、今後細分化するときに６０m2以下での敷地はできないんですよと。","voiceIndex":26,"id":"exchange-010"},{"speaker":"上山委員","kind":"質問・要望","question":"今まで６０m2以下の人はどうなるかなというような素人考えを持って、申し訳なく思ったんですが、現在もう少し少なくてそこに住んでいらっしゃる方で、建て替えるという人も、もちろん今後もつくることもあるでしょうから、そういう意味でも、新たに規制が緩和されることもありますけれども、よく住民の皆さんに説明することを含めて徹底していただきたい。最後は要望だけにしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-011"},{"speaker":"本田委員","kind":"質問","question":"ですから、１２月１０日頃までにもう一回意見交換会を開くとは言え、それも出席はちょっとどうなんだということで、周知の仕方についていろいろご議論がありましたけれども、１４０世帯の方々が今具体的にこのように案が出ているわけですから、これについて概ね賛成しているという方が圧倒的だ。つまり８割とか９割とか、そういう掌握を区のほうではまだしていないんだと思うんです。出席率だけではなくて。","respondent":"浜脇住環境整備課長","answer":"ですから、私どもはそれは日頃から検討に入って、お話をしようと言っているんですが、それについてはもう承知しているとか、分かっているからどうぞとかというようなことも、私も直接お電話なり、お会いして聞いておりますので、そういった意味では皆さん方がご案内なんだなと。","voiceIndex":29,"id":"exchange-012"},{"speaker":"本田委員","kind":"質問・要望","question":"同じことを言っても何ですが、地権者がかなり多いですからね。それを適用してやっていこうということは大変重要なことなだけに、おれは知らなかったとか、おれはいやだったんだとか、そんなのが後になってひっかかって、なかなか進んでいかないということのないように、住民の意思というものを十分確認しながら進めていただきたいと思います。要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-013"},{"speaker":"石田委員","kind":"質問","question":"東京構想２０００というところで１点お聞きをしたいのですが、センター・コア・エリアというのが括弧付きで、良好な低層住宅地として保全すべき地域等を除く。そこら辺のところはどこら辺まで突っ込んでやる気なのか、また、効力があるのかというのは、どこら辺まで見込んでいるのかというのをお聞きしたいと思います。","respondent":"伊佐都市計画課長","answer":"それは用途地域の見直しの基本的な考えですが、この辺の考え方を反映した用途地域の見直しの方針が検討が始まったところで、これがおそらく今年度末ぐらいに出てまいりますので、その基本方針をもとに用途地域の指定なども指定基準等を定めていくということですが。","voiceIndex":37,"id":"exchange-014"},{"speaker":"石田委員","kind":"質問","question":"だけれども、ここで指定をしてきたということは、これから用途地域のそういう変更に考えていく中で、そういうある程度行政の考えを前面に出して変えていくという気で出しているのか、そうすると、大分違う、逆のやり方だから。そこら辺のところはどうお考えになっているのかというのをお聞きしたいと思います。","respondent":"伊佐都市計画課長","answer":"用途地域そのものを変更して、今の住居系から商業系にいきなり変わってくるということはなくて、まず基本的に地区計画を積極的に活用するような仕組みづくりというものが、先ほどちょっと出ましたけれども、街区再編プログラムというようなところも、その辺に考えがある。","voiceIndex":39,"id":"exchange-015"},{"speaker":"石田委員","kind":"質問・要望","question":"ここに書いてある今のお話は、取り組むべき施策の内容だと思うんです。今言ったエリアを指定しておいて、あなたたちやりなさいよと。こういうことも都市計画をやるようにやっていくというんだけれども、現実的には非常に難しい話なんですよね。そこら辺は、今も要請をしていると言ったけれども、現実的にできるものに必ずつくってほしいんです。これは要望だけにしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-016"},{"speaker":"藤田委員","kind":"質問","question":"質問にならないんですが、そういう感想はありますかね、プログラムについての品川区に当てはめた場合に、どうしたらいいんだろうという、何か構想みたいなものを今後つくっていくのか、これはもうこういう計画は絵にかいた餅なので、ただ、小手先のことだけのものだけやっていればいいんだということなのか、非常に難しいと思うんですけれども、質問しているほうも難しいと思うんです。","respondent":"山室住宅指導担当部長","answer":"非常に難しい質問で、適切にご答弁できるかどうか自信はないんですが、木造住宅が好きだということは、これは歴史的に証明されていることで、ご案内のとおり、その結果が木造住宅の密集地域という形になっているわけですが。","voiceIndex":42,"id":"exchange-017"},{"speaker":"藤田委員","kind":"質問","question":"そうしますと、考えられるのは、例えば不燃建築物を建てる前に、区として何か援助しますよとか、誘導策ですよね、木造はだめですよと。ただし、不燃建築材というんですか、そういう建て方をしますと何らかの特典がありますよというぐらいの、何か道筋をつけるというのは、品川区に当てはめた場合、品川区独自でできるような、そういうことなんでしょうか。","respondent":"山室住宅指導担当部長","answer":"例えば今住宅金融公庫の見直し等がありますので、簡単にはお答えできない部分もありますが、融資制度でどういったことができるかということは、区の施策というよりも、もう少し幅広い施策の中で。","voiceIndex":44,"id":"exchange-018"},{"speaker":"三上委員","kind":"質問","question":"資料１－２で、住宅の耐震改修の推進ということで、予算要求をされて、こういうふうにしているけれども、こういったことができる人はいいんですよね。現実そういうところがあるということで、そういったところについて何らかの対応策というのを考えなければどうにもならないじゃないかと思うんですけれども、そこらあたりどう考えているか。そういう施策的な部分というのはどうなんでしょうか。","respondent":"浜脇住環境整備課長","answer":"今度この中に勧告というような話が出ているんですが、勧告するには、やはりその方の資産なり、状況なりをよく吟味してやらないと、今度、勧告することによって、その方とトラブルが起きてしまうというようなことが、逆に私どもは心配して、自分はこれでよしと思っているのに。","voiceIndex":46,"id":"exchange-019"},{"speaker":"三上委員","kind":"質問","question":"更地になったところについての処分については何らかの形で、両者が話し合っていくとかということでもやらない限り解決しませんよね。それが分かっているわけですから、そういう方法というのを考えて、何らかの対応策というのを考えてもいいんじゃないか。この人たちの家賃というのはどういうようになっているんですか。どうなんでしょうかね。","respondent":"浜脇住環境整備課長","answer":"ちょっと話は違いますけれども、実は私が今少し勉強をさせてもらっている意味で、住宅改良ということで言わせてもらいますと、この間から話題になっております旗の台、中延地区の旗の台小学校の前については、建築住宅地区改良ができないかということで。","voiceIndex":48,"id":"exchange-020"},{"speaker":"川西委員","kind":"質問","question":"これから家を建て直して、ローンを1,０００万円抱えたらどうとかと思う年齢ですよね。財政難ですから、これ以上の方針を国や都に要求しても、私は無理じゃないかというふうに思ってさっきから黙っていたんですけれども、そういう点は区はどうなんですかね、少し首脳部に申し述べて、何とか解決策はないでしょうか。例えば旗の台のあのようなところというのは、ほかにもあると思うんです。","respondent":"山室住宅指導担当部長","answer":"当然勉強会と並行して、私ども内部では、あの地区に合った事業スキームというのはどのような方法が有効なのかということは検討をしておりまして、先ほど住宅地区改良法の事業要件に合わないというご説明をさせていただいたわけですが。","voiceIndex":50,"id":"exchange-021"},{"speaker":"石田委員","kind":"質問","question":"自民党の石田と申します。せっかく今日来ていただいたので、我々も戸越１丁目の地区計画を見せていただきまして、ある程度どういうものかということをやったわけですが、これを今作成で、これからというところでしょうが、スタートからどういう形でこれをつくろうというところの意気込みから、今ここまできて、どういうふうにお考えになっているかというのをちょっとお聞きできればと思います。","respondent":"池田戸越１丁目町会長","answer":"そういう部分を共同でできる法律をつくろうかというのが、今回の私どもの感じたことだったものですから、それは隣近所の方と仲良くやるには、そういうものを一緒につくれば、できない家も広くなりますよというのが、今回の法律の一部だと思うので、また、建て替えに対しては。","voiceIndex":69,"id":"exchange-022"},{"speaker":"石田委員","kind":"質問","question":"今のお話はおっしゃるとおりで、私も斜線の緩和が入ってくるというところは、東京都で１番であるということで、非常にいいことで、３階建てを建てられるということになってくるわけですけれども、8.１haの中で1.２haを先にいこうよというお話の中で、これは私も委員会でも言っていたんですが、６０m2とお決めになったというのは、何か理由があるんでしょうか。","respondent":"池田戸越１丁目町会長","answer":"だから、その点は少し難しい部分があるんですけれども、私の気持ちとすれば、隣近所で仲良くやれば、そういうものも可能だろうという気がしております。","voiceIndex":71,"id":"exchange-023"},{"speaker":"石田委員","kind":"質問","question":"もちろん土地ですから、いいわけですけれども、これが１番でやることですから、これが品川区の中では前例になってくることだと思うんです。今品川区では開発要綱の中では５０m2でいくということですね。それで、５０m2だ、６０m2だという、そういう土地の評価がこれが前例になると、8.１ha全部になっていく可能性があるので、そこら辺はどうお考えになったのかなというところ。","respondent":"池田戸越１丁目町会長","answer":"例えば１２０m2あるならばちょうど２つで割れるんですけれども、１００m2ぴったりのところは１つしかできませんよという形にする自体が、土地を分割して、ごちゃごちゃした細かい家をつくるよりは、そういうものを少なくして。","voiceIndex":75,"id":"exchange-024"},{"speaker":"三上委員","kind":"質問","question":"しかし、開発しようとする地域に１４０世帯いるという、その出席者の認識度、この事業について、こういうことをやるんだということが、どれくらい皆さんが周知されて、ご存じなのかということがちょっと分かりかねている部分があるんです。そこらあたりはどういう状況なんでしょうか。","respondent":"池田戸越１丁目町会長","answer":"戸越町会に関しては、全部個人個人に１人ずつ当たったわけではありませんけれども、私の知っている範囲では、ほとんどの方が知っております。","voiceIndex":77,"id":"exchange-025"},{"speaker":"三上委員","kind":"質問","question":"その人たちに対しての周知というのはどういうふうにされたらよろしいんでしょうか。","respondent":"池田戸越１丁目町会長","answer":"聞いていないという方は、独身で、古くからそこに住んでいない方、中間に来まして、中間でどこかへ行くというような方だと思うんです。永住しようという物の考え方のおじいさん、おばあさん、子どもたちのほうは、そこに帰って来て住みつづけるので、その方は全部聞いております。","voiceIndex":81,"id":"exchange-026"},{"speaker":"伊藤副委員長","kind":"質問","question":"一番初めの沖田さんの話がすごく印象に残ったんです。でも、その中で、現場で希望した中では、そういうものまでも踏み込んでまでもやらないといけないという実感なんでしょうか。","respondent":"沖田旗の台中央商店会会長","answer":"若い人たちを取り込んで、まちづくりをもっと真剣に考えていくような方向づくりを、行政と、こういう委員会の中でつくっていただいて、どうやって災害に強い、まして旗の台地区は特に災害に弱いまち、ちょっと通りから外れば古い家がいっぱいありまして。","voiceIndex":87,"id":"exchange-027"},{"speaker":"宮崎委員","kind":"質問・要望","question":"さっきの強制力というお話が、もうちょっとイメージがつかめないんですけれども、例えば１回こうなったら、絶対２項道路の壁を強制的に取り払うぐらいの力があったらいいんじゃないかとか何か、強制力との関係で、もうちょっと私がイメージが持てなかったものですから、どんなものかなというのをちょっとお聞かせいただきたいと思います。","respondent":"沖田旗の台中央商店会会長、池田戸越１丁目町会長","answer":"その中心がはっきりとわからない。その辺のところを早めにできればやって、多分それに関してはそんなに大きなお金もかからないで済むんじゃないかという気がするので、できましたら、そういう方向を検討してもらえればと考えています。ここら辺がどうも、現実にうちのところで建っている建物があるんですよ。〔「できないはずだ」と呼ぶ者あり〕ところが、建っているんです。私もそれが不思議でしようがない。","voiceIndex":89,"id":"exchange-028"},{"speaker":"川西委員","kind":"質問・要望","question":"でも、例としては、区は公園を造成して、２項道路を空けて、そこに近所の人から要望があって、花壇を置かしているところもあるんですよ、うちの地域で。ですから、区の指導が甘いと言えば甘いと思う。それから、７０歳以上が３００名とおっしゃったので、非常に勉強になりましたが、これはこの事業を進めていくに当たって、１戸建てでは改築できない場合には、共同住宅も、自分のまちの中ならいいのかどうか。","respondent":"齋藤小山２丁目東部町会長","answer":"その中にポンポンと自分の土地を持っている人もいるわけです。その人たちは全然一緒にできませんので、地主がいますので。地主との話し合いもしなければならないということで、そこら辺のところがちょっと難しいんじゃないかなというような感じがするんです。","voiceIndex":93,"id":"exchange-029"},{"speaker":"上山委員","kind":"質問","question":"少しお聞きしたいんですが、共産党の上山です。さきほど、ほかの委員からも出たようですが、今度の計画では、大変ご苦労されていて、５０cmのセットバック、高さ１０ｍ、６０m2の敷地となっており、反対されている方もいらっしゃると思いますが、地区の中がこういった内容を知っていたか、また、セットバック等の認識、ジレンマについて、あらためてご感想をお願いします。","respondent":"池田戸越１丁目町会長","answer":"全部の方が認識しているわけではありません。無関心な人はいるわけで、関心のある人だけは認識しております。","voiceIndex":100,"id":"exchange-030"},{"speaker":"石田委員","kind":"質問・要望","question":"これは国だ、じゃ、国にこういうことを要望していく、東京都にこういうことを要望しなければしようがないだろうとかということを、仕分けしてやっていかないと全然意味のない提言になる可能性があるから、まとめてくるのであれば、そこら辺のことを視野に入れて、国・都、品川区・区民に対してどこまで関与できるかという問題もあるけれども、そういうところも分けてやっておいたほうがいいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":111,"id":"exchange-031"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6220#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":56550,"voices":113}},{"id":"h13-20011130-14","meetingId":"h13-cm11","date":"2001年11月30日","dateIso":"2001-11-30","committee":"行財政改革特別委員会","time":"午前１０時０７分～午前１１時５９分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を19件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"桜井委員","kind":"質問・要望","question":"だから今考えている、これまで要するに正味財産、これまでやってきた、それから今後どういう世代に何を施策を展開するかというそこのところをもうちょっと具体的に説明してほしい。それが一つ。それからもう一つは、基金のほう。逆に今度は基金のほう。基金で確かに品川は３２６億ですか。大体でいいよね。これも政策の判断というんですか。だからそのところがもう少し説明いただきたいなということです。","respondent":"市岡企画財政課長","answer":"基金ですけれども、基金はもちろん多ければ多いほどいいわけではありませんが、やはり同じように、税収が非常に好調だったバブル期には、当然これはどこの区でも、あるいは都でも区でも税収は伸びていましたけれども、何回かご説明していますけれども。","voiceIndex":5,"id":"exchange-001"},{"speaker":"桜井委員","kind":"質問","question":"そこのバランスをもちろん考えるんだけれど、区民１人当たりの８９万５,３６０円。昨年の平成１２年度のときにもたしか質問をしたんですけれども、その出し方の意味というんですか。例えば大田区が１人当たり１００万あると。それってどういう意味があるのかなというふうに大変私は疑問に思うんです。だけれども、住民サービスとの関係でどうなのかというところはちょっと複雑なんです。極端な質問ですが。","respondent":"市岡企画財政課長","answer":"それはまさにそのとおりです。それともう１点は、このバランスシートをつくる意味は、やはり今の公会計による財政分析や財政状況の説明ということが必ずしも区民の方にとっては十分ではないという反省があります。","voiceIndex":7,"id":"exchange-002"},{"speaker":"桜井委員","kind":"質問","question":"最後にちょっと意見ですけれども、正味財産というところで見たときに、国庫支出金と都道府県支出金と一般財源がありますよね。それで、これは区に入る国庫支出金であるというそれでいいわけですよね。だからそういう政策というんですか、流れによってかなり支出金とか都の支出金というのも流れるんじゃないかというふうに私は感じているんですけれど、そこの感じ方についてはどうですか。そこだけちょっと。","respondent":"市岡企画財政課長","answer":"なかなか難しいんですが、やはり私どもは財源は財源でしかないといいますか、やはりどういう施策をどういうふうに展開していくかというのは、お金が有利だからそれだけやるということでは政策は成り立たないと考えておりますので。","voiceIndex":9,"id":"exchange-003"},{"speaker":"松澤委員","kind":"意見","question":"あるいは土地がありますよね。ところが、道路の中でどういうような形でカウントしているのか。そうすると、１年ごとの単純な比較ではバランスが比較にならないと思うんですね。そうなってくると比較するのはどうするかというと、ほかの２３区が全部やっていた場合には他区とも比較になるけれども、品川区だけではなかなか比較にならないと思います。その辺の考え方はどうなのか。","respondent":"市岡企画財政課長","answer":"これを時価評価にするかどうかが大きな課題なんですが、本当は時価評価にしたほうがいいんですが、もともと取引の対象になっていないものをどうやって評価するのかとか、それから課題としてはそのとおりなんですが、どういう基準で評価するのかあたりが難しいので。","voiceIndex":11,"id":"exchange-004"},{"speaker":"田中委員","kind":"質問・要望","question":"基本的なことからまとめてお伺いしたいと思いますが、まず用語のことで、消防費というのは、区は直接消防関係の事業を行っていませんけれども、例えば防災関係のシステムとかというのはされるんですが、退職給与引当金、これは現在職員の方々の将来の退職金を確保するための引当金の分としてだろうと思いますが、一方、投資等のところの（４）で退職手当組合積立金という形、これは０ではありますが。","respondent":"市岡企画財政課長","answer":"それからもう一つは、景気の動向がどうなるかわかりませんが、デフレ傾向が続くとすると、物価も下がりますけれども、所得水準も下がりますから、文字どおり１人当たりと言いますか、納税者が負担する実質的な負担は高いときに買ったものは。","voiceIndex":13,"id":"exchange-005"},{"speaker":"田中委員","kind":"質問・要望","question":"もう一つ、要望になるのか、現在品川区は基礎的自治体としての立場でこういうのが出てきておりますが、それがいわゆる市町村並みの行政に実際になった際には、例えば先ほど言った消防費関係だとか、あと下水道だとか、その他財源的に都市計画、そういうものがもし仮に加わった場合のいわゆる品川市としてのこういうバランスシートというのはまず出すことができるのかどうか。","respondent":"市岡企画財政課長","answer":"現時点ではちょっと無理かなと思います。特に下水道のような膨大な投資的な経費とか設備を仮定の問題として譲り受ける条件とかそういうことを決めないと、ちょっと軽々に数字は想定できないのかなという感じです。","voiceIndex":15,"id":"exchange-006"},{"speaker":"辻副委員長","kind":"質問・要望","question":"そういう基準というのは、まだスタートしたばかりなんでしょうけれど、これは欧米の、先ほど話がありましたけれども、仕組みが違うといえば違うかもわからないんですけれど、基本的には税金を受けた自治体として見れば、区民から税金を受けてそれをどう使っていったかという考え方、その辺の基準みたいなものというのはあるんですかね。このバランスを見たときに、こことここがここがどういう。","respondent":"市岡企画財政課長","answer":"例えば何年間でこの財政規模との比率で正味資産が形成される量になっていくかというようなことを見ると、相対的に資産に対する財政規模の適正さということがわかってまいります。その他たくさんありますが、まだ確立したものはないようです。","voiceIndex":24,"id":"exchange-007"},{"speaker":"辻副委員長","kind":"質問","question":"それで企業の場合は投資という意思があって動く部分と、この資産形成の部分で、住んでいる住んでいないというのは全く関係なしにどんと来ちゃったり、あるいはどんと人が少なくなっちゃうと数字が例えば資産が幾ら、同じ一つ建物だったら人数がいるかいないかによってがらっと変わってしまうわけですから、その辺もわかりやすいんだけれど非常に比較というのはなかなかならないかなと。その辺は。","respondent":"市岡企画財政課長","answer":"いわゆるこの行政コスト計算書というのは、企業で言えば損益計算書に相当するような関係になるかというふうに言われておりまして、その辺もすぐにできるかどうかは別なんですが、やってみたいという考え方で、その中には先ほどの消費的な補助金ですとか、退職手当の引当金。","voiceIndex":26,"id":"exchange-008"},{"speaker":"辻副委員長","kind":"質問・要望","question":"これは要望で、また、我々がこの委員会をつくった目的でもある。新しいこれが区民に対して行政事務事業の評価あるいはバランスシートがどれだけ透明性をもって区民の方が自分たちの自治体に対して責任を持ち行政に参加していくかという一つの目安になっていくと思うんですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-009"},{"speaker":"鶴委員","kind":"質問","question":"単純なことでお伺いしたいんですけれど、土地なんかを無償譲渡を受けることがあるじゃないですか。東京都住宅と一緒に。は整備。それから例えば今後ある法人ができた場合にある建物をそこを譲渡すると、行政目的にすると。そういうのはどういうふうにしてカウントされているんですか。でも無償の場合はどういうふうにカウントしていくんですかね。","respondent":"市岡企画財政課長","answer":"ご指摘の点は一番基本的に本質的な内容なので、その辺もバランスシートだけポッと区民にご提供したから区財政をご理解いただけるというものではないということで、私どもも心していきたいとます思います。","voiceIndex":29,"id":"exchange-010"},{"speaker":"桜井委員","kind":"質問","question":"１点だけいいですか。今３００円払っていますよね、今の行政は。窓口行って決裁取って窓口に２週間以内に云々かんぬんというのが、瞬時で可能なんでしょうか。","respondent":"田中情報システム課長、中尾根企画部長","answer":"文書管理の中で情報公開の部分というのは、情報公開の担当のプロジェクトチームに入っているんですが、どの文書を特定するというのはなかなか難しいことがあって。したがいまして、今後の問題はこういうふうに行政の説明責任であるとか公開せいと言われていますから、どこまで情報を提供するのかが問題で。","voiceIndex":35,"id":"exchange-011"},{"speaker":"桜井委員","kind":"質問・要望","question":"ちょっと要望しておきます。この間から言っているように、他区では無料ですから、情報の公開が無料ですね。できるわけだけれども、品川区の場合は３００円かかっているから、１億円かけて便利なんだけど、区民にとっては一体何が便利になるのかというふうに、ちょっと大ざっぱで申しわけないんですけれども。本論ではないので、意見だけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-012"},{"speaker":"鶴委員","kind":"質問","question":"意味がちょっとわからないので、３ページの運用経費は一人１台パソコンとあるでしょ。これはどういう意味ですかね。全職員のテーブルに、それぞれのセクションの課に５人いるとすると、５人全部パソコンが配備されているということ？基本的には全職員にパソコンが配備されるということ、この一人１台というのは。","respondent":"田中情報システム課長","answer":"一人１台パソコンですが、正確には必要なところに一人１台パソコンというところで、事務系のところはほとんど一人１台パソコンなんですが、仕事の性格から税務、戸籍、国保ですとか、そういうところはホストコンピューターの業務端末を中心に業務をしているところですので。","voiceIndex":39,"id":"exchange-013"},{"speaker":"鶴委員","kind":"質問","question":"そうすると、１３８０台プラスその保育園ですけれど、学校はどうなっているのかと。学校は全く別の領域でシステム開発が行われているのか、あるいは含めて行われているのか。その点はどうなんですか。","respondent":"田中情報システム課長","answer":"来年２月の段階で校長、教頭につきましては、パソコンを配備してネットワークを構築するということで教育委員会のほうと調整がついておりますので、今月の冬休みに入るあたりから工事に入って、１月、２月ぐらいにかけてネットワークの工事を終えて、２月中には校長。","voiceIndex":41,"id":"exchange-014"},{"speaker":"鶴委員","kind":"質問","question":"そうすると、学校運営にかかわる諸々の手続き上の書類なんかをこういう電子区役所の課の中に組み込まれて、パソコンでいろいろ申請したり、案件が承認されたり、そういうことになるわけですか。それはまた別なんですか。","respondent":"田中情報システム課長","answer":"このネットワークを使う範囲、一般教員１,０００人近くいますが、一般教員が財務会計上のいろいろな処理ですとか起案等をやるということにはならないと思いますので、この部分については一般教員はネットワークの中の利用者には含めない形になると思います。","voiceIndex":43,"id":"exchange-015"},{"speaker":"鶴委員","kind":"質問","question":"そうすると、学校にこだわるようですけれど、学籍簿なんていうのはどうでしょう。ずっと過去のものまで火事あるいは戦災にあったりしなければ、どこかに保管されて、基本的には。要するにこういう情報社会の中でＩＴ機器が発達した中で、そういう学籍簿なんていうのはインプットされていくわけですか。","respondent":"中尾根企画部長","answer":"基本的には、各行政委員会につきましては、行政委員会の主体的な開発と言いますか、機械もそうですけれども、それをどうするのかという考え方があります。","voiceIndex":45,"id":"exchange-016"},{"speaker":"田中委員","kind":"意見","question":"今回のシステム導入をすることによって行政サービスを向上するとか、その部分のスピード化が図れるとか、ペーパーレスがあるんですが、ここには出ていなかったんですが、運用の仕方によっては全く違う結果になることもあり得るかなと思われるんですけれど、例えば稟議書のことが出ていましたが、従来紙ベースですと１セットで稟議書をつくってそれを各課のほうがつくって。","respondent":"田中情報システム課長","answer":"例えば図面等大きなものは、電子決裁になじまないものは紙ベースでやるものもありますが、基本的には電子決裁でいくということで運用の点について正確にルール化していきたいというふうに考えております。","voiceIndex":47,"id":"exchange-017"},{"speaker":"桜井委員","kind":"質問・要望","question":"きょうはその議論というのは時間との関係があるので。ただ、今後の日程の３回ですか、日程がある程度正副のところで今後の運営のテーマとしてどういうことをお考えになっているかちょっとまだ出されていないので、そういうことも含めて運営上可能であればその点だけ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-018"},{"speaker":"桜井委員","kind":"質問","question":"そうするといつごろになるかというのを知りたいのと、それとあわせて事務事業評価で今回２１２というとですよね。それで全体が７０６事業というふうに説明があったので、できればその７０６、それはどこを見なさいと教えてくれればそれでわかることなんですけれども、全体像と言いますか、区のほうで考えている全体像も知りたいなと思っているんです。それだけお聞きします。","respondent":"榎本行財政改革担当課長","answer":"時期なんですけれども、あと残り数回ということなんで、できる限り１月２４日の段階である程度あらましの部分をお示しできればと考えています。事業本数につきましては、今回２１２本入れましたけれども、２１２本全体の部分を委員会のほうに当てることをしています。","voiceIndex":63,"id":"exchange-019"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5696#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":32869,"voices":65}},{"id":"h13-20011207-9","meetingId":"h13-cm12","date":"2001年12月7日","dateIso":"2001-12-07","committee":"文教委員会","time":"午後１時２０分～午後１時４７分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を9件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第８６号議案、幼稚園教育職員の給与に関する条例の一部を改正する条例","agenda":"第８６号議案、幼稚園教育職員の給与に関する条例の一部を改正する条例","exchanges":[{"speaker":"高星委員","kind":"質問","question":"よくわからないんだけど、幼稚園職員というのは、都費の人ですか、区費の人ですか。区費の人で、こういうふうにしようということは、どういう段階で決まっていくのか、ちょっと教えてもらいたい。","respondent":"鷹倉庶務課長","answer":"前段の都費、区費という話ですけども、平成１２年度から区費になってございまして、今回、条例の頭にありますとおり、幼稚園の教育職員で、具体的に人数がどれだけいるかということですけど、正規職員で、園長３名、教頭２名、教員２４名、正規職員は２９名です。","voiceIndex":5,"id":"exchange-001"},{"speaker":"高星委員","kind":"意見","question":"だから、経済状況がこういうふうになってきて、この先、ますます暗闇で先が見えないところで、そういう方向はやむを得ないことなんだろうとは思うんですけど、その辺について、品川区の事業の関係で悪影響が出ないかどうか、そういった懸念がないかどうか、また経済状況から見てどうなのかということ、この二つだけちょっと聞きたいんですけど。","respondent":"鷹倉庶務課長","answer":"経済的状況云々という２番目の質問にも関連していると思うんですけども、今のところ、先行きが上向くというような状況じゃございませんので、来年も予断を許さないという厳しい状況の中で、もっと気を引き締めながら、幼稚園も含めて教育委員会も、いい仕事というか。","voiceIndex":7,"id":"exchange-002"},{"speaker":"高星委員","kind":"質問・要望","question":"これで終わりますけど、今、庶務課長がおっしゃられたこと、まさにそのとおりだと思うんで、教育委員会を挙げて、この辺のところで変な不協和音がないように、十分に職員に理解してもらえるように努めていただきたいと、これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-003"},{"speaker":"鈴木（真）委員","kind":"質問","question":"今、高星委員からお話がありましたように、仕事をしていく中で、下がるという点では、大変なことかもしれないんですが、今、民間準拠という言葉が出ましたけど、第６条の特例一時金の中において、「民間における賃金との均衡」と出ていますが、この民間の基準というのはどの辺に置いているのかなというのを、まず教えていただけますか。","respondent":"鷹倉庶務課長","answer":"民間のものというのは、ご案内かと思うんですけども、特別区人事委員会が一定の規模の事業者を対象にやっているわけです。１,０００人以上だったと思いますけども、そういうところを対象にしながら、特別区との格差を比較していくということだと思います。","voiceIndex":10,"id":"exchange-004"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"〔「そうじゃない」と呼ぶ者あり〕教育長がそうじゃないとおっしゃったけど、私も民間でしたけど、はっきり言って、給料は違いませんよ。答えられない部分だと思うんで、要望というか、その辺をまたよく考えてもらいたいなということで終わりますけど、何かその辺もよく考えた上で、これからの仕事のほうに反映していただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":12,"id":"exchange-005"},{"speaker":"桜井委員","kind":"質問・要望","question":"３点あります。一つは細かいんですけど、期末手当、勤勉手当の違いというんですか。この辺のところを教えていただきたいのが１点。それから、二つ目には、５５歳までで昇給停止というのは、何か根拠みたいなものがあるんですか。これって、人事課のほうのトータル的なものなのか、あるいは、例えば教育委員会で、頑張っている非常勤の皆さんの待遇改善というのは独自に判断できるんですか。以上、３点です。","respondent":"鷹倉庶務課長","answer":"トータルとして、公務員全体として、意欲がわくようにというような形かなと。５５歳と５４歳でどこが違いがあるのかと言われると、なかなか難しいんですけども、今の全体の職員の構成だとか、そういう中で出てくるものなのかなという理解をしています。","voiceIndex":13,"id":"exchange-006"},{"speaker":"桜井委員","kind":"質問・要望","question":"非常勤のほうは、独自に教育委員会としてやるということは可能なんですか、どうなんですか。それで、やる意志があるのかどうかというところを、もう少し聞きたいんです。いずれにしても、率直に大変だなと思うし、線引きがどこにどういうふうに、気持ちだけとなるんでしょうけども、負けずに頑張っていただきたいと思います。","respondent":"指田教育次長","answer":"そういういったベースの中から考えると、区の職員、あるいは都の職員、公務員もそうですけども、やはり高齢職員がずっとそのまま昇っていっていいんだろうか、やはり一定程度まで来たら、横に行く、とまるというのが基本ではないかというのが。","voiceIndex":15,"id":"exchange-007"},{"speaker":"川西委員","kind":"意見","question":"ちょっとその中で、もしわからなかったらご答弁はいいですけど、人事委員会の方向性が、今は５５歳で昇給停止になったけれども、将来は、今、次長がおっしゃったように、もしかして５３歳にするかもしれないとか、５０歳にするとか、これは１０年先かもしれないけれども、そういう傾向と議論というのがあったかどうか、聞いていますか。それが一つ。４７歳とか書いてありますよね、段階的に。","respondent":"鷹倉庶務課長","answer":"後段のほうで、９年間かけて３年で１歳ずつということですが、経過の中で、当初、６年という話が出ていて、最終的に３年下りて９年の経過措置になったという話を聞いてあります。","voiceIndex":17,"id":"exchange-008"},{"speaker":"高星委員","kind":"質問・要望","question":"幼稚園の先生方は、教諭という形になると、教務手当とか関係ないんですか。幼稚園の先生方には、教務手当というのは出てないんでしたっけ。同じ区立幼稚園の中で、前にどこかで、職員の給料をその区だけ減らしたというところがあったような気がするんですけど、現実的には、うちの区の職員よりももっと給料が下がっているという区もあるということなのか、現況を知っている限りでちょっと教えていただきたい。","respondent":"鷹倉庶務課長","answer":"前段のお話ですけども、今回、ほかの手当について跳ね返ってはいないです。それから、ほかの区の状況ですけども、今年度分については、これから制度で動いているわけですけども、今年の３月末で、議会でいろいろ動きがあって、独自の動きをしたところが３区あったということです。","voiceIndex":19,"id":"exchange-009"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4426#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":8349,"voices":24}},{"id":"h13-20011207-5","meetingId":"h13-cm12","date":"2001年12月7日","dateIso":"2001-12-07","committee":"総務委員会","time":"午後１時２１分～午後１時５３分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を10件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第８５号議案、職員の給与に関する条例の一部を改正する条例","agenda":"第８５号議案、職員の給与に関する条例の一部を改正する条例","exchanges":[{"speaker":"塚本委員","kind":"質問・要望","question":"今、説明の中でも前回総務委員会等で公務員の給与に関する民間の思いというものについての委員会での言及があったという報告がありましたけれども、それはあえて繰り返しませんけれども、そのことはよく踏まえていただきたいということです。それで、具体的に１点聞きます。３年間ごとに、３回変えるということですね。どうしてこんなことになっちゃったのか教えてください。","respondent":"古川秘書課長兼務人事課長","answer":"実は、東京都が昨年度、この昇給停止については一定の決定を見たんですが、経過措置を実は１４年の４月１日から実施すると。しかも９年間ということで既に東京都が一定の考え方を出した。こういうことが一つの背景です。","voiceIndex":5,"id":"exchange-001"},{"speaker":"塚本委員","kind":"意見","question":"あまりよろしくお願いされたくないですね。こういう決め方をするから、みんなよくわけのわかっている人は何やっているんだという話になる。いい方向に変えようとするならば、多少の痛みがあるのは当たり前ですよ。痛みは人に押しつけておいて、自分の決め事を変えるとき、こんな緩やかな変え方をするということは非常に問題です。ほかに一当たりしてから言いたいこともありますので、あんばいを見ながら。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":7,"id":"exchange-002"},{"speaker":"宮崎委員","kind":"質問","question":"ちょっと伺いたいんですけども、この0.５カ月減ということで、これで標準の職員といいますか、その方の給与がどういうふうに変わるのかということが、どんなものかと思いますけど。それとあとは、初任給なんかもどういうふうに変わっていくのかという問題と、そこら辺のモデルといいますか、ありましたら、お伺いをしたいというふうに思います。","respondent":"古川秘書課長兼務人事課長","answer":"今回のこの措置による影響ということで、まず期末手当の0.０５月減ですけれども、一般職全体で平均をとらえますと約２万2,０００円ぐらいをこの分でとられます、年間ですけれども、この減で。","voiceIndex":8,"id":"exchange-003"},{"speaker":"宮崎委員","kind":"質問","question":"前回は何か２３区というのでちょっと足並みがそろわなかったということなんですけど、ちょっと今の時期でどんなもんかというのは、ちょっとまだ判断つかないかもしれないんですけど、その辺の動きはどんなふうになっているのかということが一つと、これはちょっと聞いてもどういうふうな答えが返ってくるかわからないんですけど、参考のためにちょっと伺いたいんですけど、今非常に消費不況の中で。","respondent":"古川秘書課長兼務人事課長","answer":"基本的には、いわゆる統一基準に関して申し上げますと、それぞれ各区がそれでもって実施すると、この定めの中で基本的には各区が対応することだろうと思っています。昨年はそういう中での３区が例外的な措置をした、こういうことです。","voiceIndex":10,"id":"exchange-004"},{"speaker":"林（宏）委員","kind":"質問","question":"ちょっと最初に、この比較表の見方なんだけども、この真ん中の表の例えば上の一番左、３月期は0.５５月と書いてありますよね。この0.５５月というのは、さっき合計4.７カ月と言ったのと、例えば0.５５月というのは、どういう数字なの。ここに書かれている4.７カ月というのは、4.７カ月分ですよという意味で、ここに書かれている月というのは、どういう意味なのか、ちょっと教えてください。","respondent":"古川秘書課長兼務人事課長","answer":"これは３月期の例ですけれども、ベースになりますのは給与月額、それに対しまして、いわゆる給与月額に対する……。","voiceIndex":12,"id":"exchange-005"},{"speaker":"林（宏）委員","kind":"質問","question":"もう一回聞き直します。例えば、今僕が言った１００というのは、パーセンテージで１００じゃなくて、もうちょっとわかりにくい数字で、５００円月額給与賃金があったとする。0.５５カ月だと２７円５０銭。そういう計算の仕方をするのか、さっき言った4.７カ月分というのは、また違うわけですよね。何カ月分というのと、ここの3.９０月というのと、どういうふうに違うのか、違いを教えてくれる。","respondent":"古川秘書課長兼務人事課長","answer":"すみません。それはそれぞれの給与月額に対しまして、一定の率を掛けたものをそれぞれ３月、６月、１２月の期末手当ということで、年間トータルでしますと3.９月分、これが支給される。その内訳は３月、６月、１２月と……。","voiceIndex":16,"id":"exchange-006"},{"speaker":"林（宏）委員","kind":"質問","question":"はい、わかりました。それから、もう一つは、人事委員会勧告を受けて、さっきも話したけど、どこまで議会が踏み込んで話ができるかわかりませんけど、労使の合意を得るために、組合と話し合いをするわけですよね。細かいやりとりはいいですから。","respondent":"古川秘書課長兼務人事課長","answer":"ですから、勧告どおりになるかならないかは、その協議の一つの結果の中にあらわれてまいりますし、その結果を受けて、特に２３区は連合の人事委員会ですので、２３区はその結果をそれぞれの区の中で当然給与は条例事項です。条例によって定めると。","voiceIndex":24,"id":"exchange-007"},{"speaker":"林（宏）委員","kind":"質問","question":"人事委員会の勧告の受けとめ方、お話の中にもちらっとバブル期というか、右肩上がりというか、いいときはそれなりの数字が出てくるから、よしとするんでしょうけど、こういう時期になってきたときに、今回人事委員会の勧告どおりで合意を見たという、結果的にはそういうことになってきているわけだけど、一つずつ下がるのは嫌だとか、もちろんだれでもそうですけど。","respondent":"古川秘書課長兼務人事課長","answer":"直接は聞いてございませんが、その他の形で流れてまいります、情報の中に。引き金は先ほど、昨年３区が、いわゆる交渉を行い、妥結した結果を、各区が基本的には誠実に実行する義務があるという中で交渉を委任してやっているわけなんですが、３区がそうじゃない内容のものだった。","voiceIndex":26,"id":"exchange-008"},{"speaker":"宮崎委員","kind":"質問","question":"すみません。ちょっと忘れていたんですが、非常勤の職員というのは全然影響ないんですか。あったら、どんな感じでやるのか。","respondent":"古川秘書課長兼務人事課長","answer":"今回のその改定については、非常勤は基本的には関連してございません。","voiceIndex":28,"id":"exchange-009"},{"speaker":"塚本委員","kind":"質問","question":"そういう場面が多いわけですけど、現実はなかなかどういう仕組みでどうなって、非常にテクニカルな部分がありますし、わからないのが多いんですよね。ですから、もう少し説明がしやすいような給与の決め方、出し方をすべきではないかと思います。やっていないなら我々が言うし、また、理事者側もそういうことを課題としてとらえるべき時期に来ているんではないかと思いますけど、どうでしょうか。","respondent":"古川秘書課長兼務人事課長","answer":"一つには年俸、しかも職層なり、年齢なり、そういったものをもう少し具体的につかみやすいような形、こういったものは、今年につきましては、１２月ということで既に出していますけども、年に１回給与の公表というものがありますので、この中で今のご意見につきましては。","voiceIndex":30,"id":"exchange-010"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1568#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":9898,"voices":35}}]);
